"""오프닝 해설(영어·한국어). 수순은 처음 국면부터 SAN, 빈칸으로 나눈다. build.py가 모든 수순을 chess로 둬 보고,
end='mate'인 함정은 실제로 체크메이트인지 확인한다(틀리면 빌드가 멈춘다).
covers = 이 해설이 맡는 리체스 이름(갈래 이름 전체, 또는 '갈래: 변화' 앞부분). 가장 긴 것이 이긴다."""

GROUPS = [
    ('e4e5', {'en': '1.e4 e5: open games', 'ko': '1.e4 e5: 오픈 게임'}),
    ('sicilian', {'en': '1.e4 c5: the Sicilian', 'ko': '1.e4 c5: 시실리안'}),
    ('e4other', {'en': 'Other answers to 1.e4', 'ko': '1.e4에 다른 응수: 세미 오픈 게임'}),
    ('d4', {'en': '1.d4 d5: closed games', 'ko': '1.d4 d5: 클로즈드 게임'}),
    ('indian', {'en': '1.d4 Nf6: Indian defenses', 'ko': '1.d4 Nf6: 인디언 디펜스'}),
    ('d4other', {'en': 'Other answers to 1.d4', 'ko': '1.d4에 다른 응수'}),
    ('flank', {'en': 'Flank openings', 'ko': '플랭크(측면) 오프닝'}),
    ('irregular', {'en': 'Rare first moves', 'ko': '드문 첫 수: 이레귤러 오프닝'}),
]

OPENINGS = []


def O(slug, side, group, line, covers, en, ko, vars=(), traps=(), hub=False):
    # hub=True: 한 오프닝이 아니라 갈래를 모아 보여 주는 길잡이(1.e4 e5, 2.Nf3 등). 홈 '많이 두는 오프닝'과 글의 표에서는 뺀다.
    OPENINGS.append(dict(slug=slug, side=side, group=group, line=line, covers=covers, en=en, ko=ko,
                         vars=list(vars), traps=list(traps), hub=hub))


def V(line, en_name, en_note, ko_name, ko_note):
    return dict(line=line, en=dict(name=en_name, note=en_note), ko=dict(name=ko_name, note=ko_note))


def TR(line, en_title, en_text, ko_title, ko_text, end=None):
    return dict(line=line, end=end, en=dict(title=en_title, text=en_text), ko=dict(title=ko_title, text=ko_text))


