O('sicilian-defense', 'b', 'sicilian', 'e4 c5', ['Sicilian Defense'],
  en=dict(name='Sicilian Defense', title='Sicilian Defense: Main Lines Explained with Stats by Rating',
          desc='The Sicilian Defense (1.e4 c5): Open Sicilian, Alapin, Closed, Smith-Morra and Rossolimo, what each side wants and how often each line happens.',
          lead='1...c5 fights for d4 from the side instead of copying White. The position becomes unbalanced from move one, which is why it is the most popular answer to 1.e4 among strong players.',
          white=['2.Nf3 and 3.d4 is the Open Sicilian: more space and attacking chances, but a lot of theory.',
                 '2.c3 (Alapin), 2.Nc3 (Closed) and 3.Bb5 (Rossolimo, Moscow) are anti-Sicilians: they avoid the theory and still give a good game.',
                 'In the Open Sicilian White often castles long and pushes the kingside pawns.'],
          black=['After 3.d4 cxd4 4.Nxd4 you have a central pawn majority and the half-open c-file.',
                 'Choose one system against the Open Sicilian (...d6, ...Nc6 or ...e6) and learn its pawn structure.',
                 'Counterplay comes on the queenside: ...a6, ...b5 and pressure on c3.'],
          club='Below 2000 a large share of Sicilians are not Open Sicilians at all: White plays 2.Bc4, 2.Nc3, 2.c3 or 2.d4 gambits. Use the table above to see which ones your opponents actually play before you learn 20 moves of Najdorf.'),
  ko=dict(name='시실리안 디펜스', title='시실리안 디펜스: 주요 갈래 정리와 레이팅별 응수',
          desc='시실리안 디펜스(1.e4 c5) 정리: 오픈 시실리안, 알라핀, 클로즈드, 스미스-모라, 로솔리모, 양쪽이 원하는 것과 각 갈래가 얼마나 나오는지.',
          lead='1...c5는 백을 따라 하지 않고 옆에서 d4를 다퉈요. 첫 수부터 판이 비대칭이 돼서, 강한 사람들 사이에서 1.e4에 대한 가장 인기 있는 응수예요.',
          white=['2.Nf3와 3.d4가 오픈 시실리안이에요. 공간과 공격 기회가 많지만 이론도 많아요.',
                 '2.c3(알라핀), 2.Nc3(클로즈드), 3.Bb5(로솔리모·모스크바)는 안티 시실리안이에요. 이론을 피하면서도 좋은 판을 줘요.',
                 '오픈 시실리안에서 백은 긴 캐슬링 뒤 킹 쪽 폰을 자주 밀어요.'],
          black=['3.d4 cxd4 4.Nxd4 뒤엔 중앙 폰이 하나 더 많고 c파일이 반쯤 열려요.',
                 '오픈 시실리안에는 체계 하나(...d6, ...Nc6, ...e6)를 골라 그 폰 구조를 익혀요.',
                 '반격은 퀸 쪽에서: ...a6, ...b5, c3 압박.'],
          club='2000 아래 시실리안 상당수는 오픈 시실리안이 아니에요. 백이 2.Bc4, 2.Nc3, 2.c3, 2.d4 갬빗을 둬요. 나이도르프 20수를 외우기 전에 위 표에서 상대가 실제로 뭘 두는지 먼저 보세요.'),
  vars=[V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3', 'Open Sicilian with 2...d6', 'The gateway to the Najdorf (5...a6), Dragon (5...g6) and Classical (5...Nc6).',
          '오픈 시실리안, 2...d6', '나이도르프(5...a6), 드래곤(5...g6), 클래시컬(5...Nc6)로 가는 길이에요.'),
        V('e4 c5 Nf3 Nc6', 'Old Sicilian, 2...Nc6', 'The most common second move. After 3.d4 cxd4 4.Nxd4 it leads to the Sveshnikov, the Accelerated Dragon or the Classical.',
          '올드 시실리안, 2...Nc6', '가장 많이 두는 두 번째 수예요. 3.d4 cxd4 4.Nxd4 뒤 스베시니코프, 가속 드래곤, 클래시컬로 이어져요.'),
        V('e4 c5 Nf3 e6', 'French Sicilian, 2...e6', 'Black keeps ...d5 in reserve. After 3.d4 cxd4 4.Nxd4 come the Kan (4...a6) and the Taimanov (4...Nc6), each with its own guide.',
          '프렌치 시실리안, 2...e6', '흑이 ...d5를 남겨 둬요. 3.d4 cxd4 4.Nxd4 뒤 칸(4...a6)과 타이마노프(4...Nc6)로 가고, 둘 다 따로 해설이 있어요.'),
        V('e4 c5 Nf3 Nc6 Bb5', 'Rossolimo', 'White avoids the Open Sicilian and often takes on c6 to damage Black’s pawns. The Rossolimo has its own guide.',
          '로솔리모', '백이 오픈 시실리안을 피하고, c6에서 바꿔 흑 폰 구조를 망가뜨리는 일이 많아요. 로솔리모는 따로 해설이 있어요.'),
        V('e4 c5 c3', 'Alapin', 'White prepares d4 to get a full center. Black answers 2...d5 or 2...Nf6.',
          '알라핀', '백이 d4를 준비해 중앙을 채우려 해요. 흑은 2...d5나 2...Nf6.'),
        V('e4 c5 Nc3', 'Closed Sicilian', 'A slow kingside build-up with g3, Bg2, f4 and Nf3. The Closed Sicilian has its own guide.',
          '클로즈드 시실리안', 'g3, Bg2, f4, Nf3로 킹 쪽을 천천히 쌓아요. 클로즈드 시실리안은 따로 해설이 있어요.'),
        V('e4 c5 Nf3 a6', "O'Kelly, 2...a6", 'A waiting move: after 3.d4 cxd4 4.Nxd4 Nf6 5.Nc3 e5 White’s knight has no b5 square. At 2000+ White prefers 3.c3 or 3.c4.',
          '오켈리, 2...a6', '기다리는 수예요. 3.d4 cxd4 4.Nxd4 Nf6 5.Nc3 e5 뒤 백 나이트가 b5로 못 가요. 2000 이상의 백은 3.c3나 3.c4를 더 둬요.'),
        V('e4 c5 Nf3 Nf6 e5 Nd5 Nc3', 'Nimzowitsch, 2...Nf6', 'Black invites 3.e5. After 3...Nd5 4.Nc3 White gains space and Black must be precise.',
          '님조비치, 2...Nf6', '흑이 3.e5를 불러들여요. 3...Nd5 4.Nc3 뒤 백이 공간을 얻고 흑은 정확하게 둬야 해요.'),
        V('e4 c5 b4', 'Wing Gambit, 2.b4', 'White gives the b-pawn to pull Black’s c-pawn away from d4. Most players take it: 2...cxb4.',
          '윙 갬빗, 2.b4', '백이 b폰을 줘서 흑 c폰을 d4에서 떼어 내요. 대부분 2...cxb4로 받아요.'),
        V('e4 c5 Bc4', 'Bowdler Attack (2.Bc4)', 'Very common at low ratings. 2...e6 blunts the bishop and prepares ...d5.',
          '보들러 어택(2.Bc4)', '낮은 레이팅에서 아주 흔해요. 2...e6로 비숍을 막고 ...d5를 준비해요.')],
  traps=[])

O('sicilian-najdorf', 'b', 'sicilian', 'e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6', ['Sicilian Defense: Najdorf Variation', 'Sicilian Defense: Sozin Attack, Flank Variation'],
  en=dict(name='Sicilian Najdorf', title='Sicilian Najdorf: Main Lines, Plans and Stats by Rating',
          desc='The Najdorf Sicilian (5...a6): English Attack, 6.Bg5, 6.Be2 and 6.Bc4 explained, with the plans for each and real reply rates by rating.',
          lead='5...a6 is a small move with a big idea: it keeps White’s pieces off b5 and prepares ...e5 or ...e6 and ...b5. Fischer and Kasparov played it all their lives; it is the most respected answer in the Open Sicilian.',
          white=['6.Be3 with f3, Qd2 and O-O-O (English Attack) is the modern main line.',
                 '6.Bg5 is the sharpest; 6.Be2 and 6.h3 are calmer.',
                 '6.Bc4 aims at e6 and f7; Black meets it with ...e6 and ...b5.'],
          black=['Choose your structure: ...e5 (gaining space, d5 is the weak square) or ...e6 (Scheveningen-style).',
                 'Queenside play with ...b5–b4 is your main counterattack.',
                 'Do not castle into a pawn storm without counterplay ready.'],
          club='The Najdorf is less common below 2000 than its reputation suggests, because White often avoids the Open Sicilian. When you do get it, 6.Bg5 is White’s most common choice at every rating level here, with 6.Be3, 6.Bc4 and 6.Bd3 next. Learn the plans against 6.Bg5, 6.Be3 and 6.Bc4 first.'),
  ko=dict(name='시실리안 나이도르프', title='시실리안 나이도르프: 주요 수순·계획·레이팅별 응수',
          desc='나이도르프 시실리안(5...a6) 정리: 잉글리시 어택, 6.Bg5, 6.Be2, 6.Bc4 갈래별 계획과 레이팅별 실제 응수 비율.',
          lead='5...a6는 작은 수지만 생각이 커요. 백 말이 b5에 오지 못하게 하고 ...e5나 ...e6와 ...b5를 준비해요. 피셔와 카스파로프가 평생 둔 수이고, 오픈 시실리안에서 가장 존중받는 응수예요.',
          white=['6.Be3 뒤 f3, Qd2, O-O-O(잉글리시 어택)가 요즘 주요 수순이에요.',
                 '6.Bg5가 가장 날카롭고, 6.Be2와 6.h3는 차분해요.',
                 '6.Bc4는 e6·f7을 겨눠요. 흑은 ...e6와 ...b5로 받아요.'],
          black=['구조를 골라요: ...e5(공간을 얻고 d5가 약한 칸) 또는 ...e6(셰베닝겐식).',
                 '...b5–b4로 퀸 쪽을 미는 게 주된 반격이에요.',
                 '반격 준비 없이 폰 폭풍이 오는 쪽으로 캐슬링하지 않아요.'],
          club='2000 아래에서는 백이 오픈 시실리안을 피하는 일이 많아서 나이도르프가 이름값만큼 자주 나오진 않아요. 나왔을 때 백은 모든 레이팅대에서 6.Bg5를 가장 많이 두고, 6.Be3, 6.Bc4, 6.Bd3가 그다음이에요. 6.Bg5, 6.Be3, 6.Bc4에 맞선 계획부터 익히세요.'),
  vars=[V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6 Be3 e5 Nb3 Be6 f3', 'English Attack', 'White castles long and storms with g4–g5. Black plays ...Be6, ...Nbd7 and ...b5.',
          '잉글리시 어택', '백은 긴 캐슬링 뒤 g4–g5로 밀어요. 흑은 ...Be6, ...Nbd7, ...b5.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6 Bg5 e6 f4', '6.Bg5', 'The old main line, full of sharp lines such as the Poisoned Pawn (7...Qb6).',
          '6.Bg5', '독 든 폰(7...Qb6) 같은 날카로운 갈래가 가득한 옛 주요 수순이에요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6 Be2 e5 Nb3 Be7', '6.Be2 (Opočenský)', 'A positional line. Black plays ...e5 and fights for d5.',
          '6.Be2(오포첸스키)', '포지션 갈래예요. 흑은 ...e5로 d5를 다퉈요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6 Bc4 e6 Bb3 b5', '6.Bc4 (Fischer-Sozin)', 'The bishop aims at e6. Black blunts it with ...e6 and chases it with ...b5.',
          '6.Bc4(피셔-소진)', '비숍이 e6을 겨눠요. 흑은 ...e6로 막고 ...b5로 쫓아요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6 Bg5 e6 f4 Qb6 Qd2 Qxb2 Rb1 Qa3', 'Poisoned Pawn, 7...Qb6', 'Black grabs b2 and the queen runs to a3. It is sharp and deeply analyzed, and almost every game here that reaches it is at 2000+.',
          '독 든 폰, 7...Qb6', '흑이 b2를 먹고 퀸이 a3로 피해요. 아주 날카롭고 깊이 연구된 갈래라서, 여기서 이 국면까지 간 판은 거의 다 2000 이상이에요.')],
  traps=[])

O('sicilian-dragon', 'b', 'sicilian', 'e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 g6',
  ['Sicilian Defense: Dragon Variation', 'Sicilian Defense: Accelerated Dragon', 'Sicilian Defense: Hyperaccelerated Dragon'],
  en=dict(name='Sicilian Dragon', title='Sicilian Dragon: Yugoslav Attack, Plans and Stats by Rating',
          desc='The Sicilian Dragon (5...g6): the Yugoslav Attack, the Accelerated Dragon, the 6.Be3 Ng4? trick and how often each line is played at your rating.',
          lead='5...g6 puts the bishop on g7, where it breathes fire down the long diagonal. Opposite-side castling races are typical: White attacks the king, Black attacks on the c-file.',
          white=['The Yugoslav Attack (Be3, f3, Qd2, O-O-O, h4–h5) is the most dangerous plan.',
                 'Trade the g7 bishop with Bh6 when you can; the Dragon is much weaker without it.',
                 'Quieter lines with Be2 and O-O are easier to play but less testing.'],
          black=['Castle short, put a rook on c8, and use ...Ne5–c4 to fight White’s bishop.',
                 'The exchange sacrifice ...Rxc3 is a key idea to break White’s queenside.',
                 'The Accelerated Dragon (...Nc6 and ...g6 without ...d6) aims for ...d5 in one go.'],
          club='Almost every player answers 6.Be3 with 6...Bg7, but the 6...Ng4? trick below is worth knowing from both sides. Beyond that, the race matters more than memory: count who gets there first.'),
  ko=dict(name='시실리안 드래곤', title='시실리안 드래곤: 유고슬라브 어택·계획·레이팅별 응수',
          desc='시실리안 드래곤(5...g6) 정리: 유고슬라브 어택, 가속 드래곤, 6.Be3 Ng4? 수, 레이팅별로 각 갈래가 얼마나 나오는지.',
          lead='5...g6는 비숍을 g7에 놔요. 비숍이 긴 대각선을 따라 불을 뿜는 모양이라 드래곤이에요. 서로 반대쪽으로 캐슬링하고 경주하는 판이 흔해요. 백은 킹을, 흑은 c파일을 공격해요.',
          white=['유고슬라브 어택(Be3, f3, Qd2, O-O-O, h4–h5)이 가장 위험한 계획이에요.',
                 '할 수 있으면 Bh6로 g7 비숍을 바꿔요. 그 비숍이 없으면 드래곤이 훨씬 약해요.',
                 'Be2와 O-O로 가는 조용한 갈래는 두기 쉽지만 덜 까다로워요.'],
          black=['짧은 캐슬링, c8에 룩, ...Ne5–c4로 백 비숍과 싸워요.',
                 '익스체인지 희생 ...Rxc3로 백 퀸 쪽을 깨는 게 핵심이에요.',
                 '가속 드래곤(...d6 없이 ...Nc6와 ...g6)은 ...d5를 한 번에 노려요.'],
          club='6.Be3에는 거의 모두 6...Bg7를 두지만, 아래 6...Ng4? 함정은 양쪽 다 알아 둘 만해요. 그다음부터는 외우기보다 경주예요. 누가 먼저 닿는지 세어 보세요.'),
  vars=[V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 g6 Be3 Bg7 f3 O-O Qd2 Nc6 Bc4', 'Yugoslav Attack, 9.Bc4', 'The main line. White castles long and pushes h4–h5; Black plays ...Bd7, ...Rc8 and ...Ne5.',
          '유고슬라브 어택, 9.Bc4', '주요 수순이에요. 백은 긴 캐슬링과 h4–h5, 흑은 ...Bd7, ...Rc8, ...Ne5.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 g6 Be2 Bg7 O-O O-O', 'Classical Dragon', 'Both sides castle short. Slower and more positional.',
          '클래시컬 드래곤', '둘 다 짧은 캐슬링을 해요. 더 느리고 포지션 위주예요.'),
        V('e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 g6', 'Accelerated Dragon', 'Black delays ...d6 to play ...d5 in one move. White can grab space with c4 (Maróczy Bind).',
          '가속 드래곤', '흑이 ...d6를 미루고 ...d5를 한 번에 노려요. 백은 c4(마로치 바인드)로 공간을 잡을 수 있어요.'),
        V('e4 c5 Nf3 g6 d4 cxd4 Qxd4 Nf6 e5 Nc6 Qa4 Nd5', 'Hyperaccelerated Dragon, 2...g6', 'Black skips ...Nc6 as well. 3.d4 cxd4 4.Qxd4 eyes h8 at once, and 4...Nf6 5.e5 Nc6 6.Qa4 Nd5 is the main answer.',
          '초가속 드래곤, 2...g6', '흑이 ...Nc6까지 건너뛰어요. 3.d4 cxd4 4.Qxd4는 바로 h8을 노리고, 4...Nf6 5.e5 Nc6 6.Qa4 Nd5가 주된 응수예요.')],
  traps=[TR('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 g6 Be3 Ng4 Bb5+ Bd7 Qxg4 Bxb5 Ndxb5', '6.Be3 Ng4? 7.Bb5+',
            '6...Ng4 hits the e3 bishop, but 7.Bb5+! wins a piece: after 7...Bd7 8.Qxg4 Bxb5 9.Ndxb5 White is a knight up. Black should play 6...Bg7 first.',
            '6.Be3 Ng4? 7.Bb5+', '6...Ng4는 e3 비숍을 치지만 7.Bb5+!로 말 하나를 잃어요. 7...Bd7 8.Qxg4 Bxb5 9.Ndxb5면 백이 나이트 하나 많아요. 흑은 먼저 6...Bg7.')])

O('smith-morra-gambit', 'w', 'sicilian', 'e4 c5 d4 cxd4 c3', ['Sicilian Defense: Smith-Morra Gambit', 'Sicilian Defense: Smith-Morra Gambit Accepted',
   'Sicilian Defense: Smith-Morra Gambit Declined', 'Sicilian Defense: Smith-Morra Gambit Deferred'],
  en=dict(name='Smith-Morra Gambit', title='Smith-Morra Gambit: Lines, the Siberian Trap and Stats by Rating',
          desc='The Smith-Morra Gambit (1.e4 c5 2.d4 cxd4 3.c3): accepted and declined lines, the Siberian trap, plans for both sides and reply rates by rating.',
          lead='3.c3 gives a pawn to get fast development and open lines against the Sicilian. White’s pieces flood the board (Nc3, Nf3, Bc4, O-O, Qe2, Rd1) while Black is still finishing development.',
          white=['After 3...dxc3 4.Nxc3, aim the pieces at d6 and f7: Bc4, Nf3, O-O, Qe2 and Rd1.',
                 'The open c- and d-files are your compensation; use them before Black catches up.',
                 'If Black declines with 3...Nf6 or 3...d5, you get an Alapin-style game.'],
          black=['Accepting is fine; develop with ...Nc6, ...e6, ...a6 and ...Nge7 or ...Nf6, and castle.',
                 'Declining with 3...Nf6 4.e5 Nd5 or 3...d5 avoids all the theory.',
                 'Watch out for Nb5 and Nd5 jumps and the Siberian trap (below).'],
          club='Below 2000 White scores better with the Morra than in the average Sicilian. As Black, if you do not know the lines, decline it.'),
  ko=dict(name='스미스-모라 갬빗', title='스미스-모라 갬빗: 수순·시베리안 함정·레이팅별 응수',
          desc='스미스-모라 갬빗(1.e4 c5 2.d4 cxd4 3.c3) 정리: 수락·거절 갈래, 시베리안 함정, 양쪽 계획과 레이팅별 응수 비율.',
          lead='3.c3는 폰을 줘서 시실리안을 상대로 빠른 전개와 열린 길을 얻어요. 흑이 전개를 끝내기 전에 백 말들이 판을 채워요(Nc3, Nf3, Bc4, O-O, Qe2, Rd1).',
          white=['3...dxc3 4.Nxc3 뒤 말들을 d6와 f7로 겨눠요: Bc4, Nf3, O-O, Qe2, Rd1.',
                 '열린 c·d파일이 폰 값이에요. 흑이 따라잡기 전에 써요.',
                 '흑이 3...Nf6나 3...d5로 거절하면 알라핀 같은 판이 돼요.'],
          black=['받아도 괜찮아요. ...Nc6, ...e6, ...a6, ...Nge7나 ...Nf6로 전개하고 캐슬링해요.',
                 '3...Nf6 4.e5 Nd5나 3...d5로 거절하면 이론을 다 피해요.',
                 'Nb5·Nd5 점프와 시베리안 함정(아래)을 조심해요.'],
          club='2000 아래에서는 모라를 두면 백 성적이 시실리안 평균보다 좋아요. 흑이고 갈래를 모르면 거절하세요.'),
  vars=[V('e4 c5 d4 cxd4 c3 dxc3 Nxc3 Nc6 Nf3 d6 Bc4 e6 O-O Nf6 Qe2 Be7 Rd1', 'Accepted, main line', 'White has full development; Black is solid and a pawn up. The battle is over d6.',
          '수락 주요 수순', '백은 전개를 다 했고, 흑은 단단하고 폰 하나 많아요. d6를 두고 싸워요.'),
        V('e4 c5 d4 cxd4 c3 Nf6 e5 Nd5', 'Declined with 3...Nf6', 'Black transposes to an Alapin-style position and avoids the gambit.',
          '3...Nf6 거절', '흑이 알라핀 같은 판으로 옮겨 가며 갬빗을 피해요.'),
        V('e4 c5 d4 cxd4 c3 d5 exd5 Qxd5 cxd4', 'Declined with 3...d5', 'Black hits the center at once. Simple and good.',
          '3...d5 거절', '흑이 바로 중앙을 쳐요. 단순하고 좋아요.')],
  traps=[TR('e4 c5 d4 cxd4 c3 dxc3 Nxc3 Nc6 Nf3 e6 Bc4 Qc7 O-O Nf6 Qe2 Ng4 h3 Nd4 Nxd4 Qh2#', 'The Siberian trap',
            'In this common setup, 9.h3?? walks into 9...Nd4!: the knight hits the queen, and 10.Nxd4 allows 10...Qh2 mate. Before you play h3 here, look at what the g4 knight and the c7 queen do to h2.',
            '시베리안 함정', '흔한 이 배치에서 9.h3??는 9...Nd4!에 걸려요. 나이트가 퀸을 치고, 10.Nxd4면 10...Qh2로 메이트예요. 여기서 h3를 두기 전에 g4 나이트와 c7 퀸이 h2를 함께 노리는지 보세요.', end='mate')])

O('alapin-sicilian', 'w', 'sicilian', 'e4 c5 c3', ['Sicilian Defense: Alapin Variation', 'Sicilian Defense: Delayed Alapin Variation'],
  en=dict(name='Alapin Sicilian', title='Alapin Sicilian (2.c3): Lines, Plans and Stats by Rating',
          desc='The Alapin Sicilian (1.e4 c5 2.c3): 2...d5, 2...Nf6 and other replies, plans for both sides and how often each is played at your rating.',
          lead='2.c3 prepares d4 so that White can take back with a pawn and keep a full center. It avoids the huge theory of the Open Sicilian and is easy to learn.',
          white=['Against 2...Nf6, push 3.e5 Nd5 4.d4 and develop with Nf3, Bc4 or Bd3.',
                 'Against 2...d5, 3.exd5 Qxd5 4.d4 and the queen will be chased with Nc3 later.',
                 'You often get an isolated queen’s pawn on d4: use it for piece activity.'],
          black=['2...d5 and 2...Nf6 are the two best answers; both hit e4 before d4 arrives.',
                 '...e6, ...Nc6 and ...cxd4 at the right moment are common in both lines.',
                 'If White gets an isolated pawn, blockade it on d5 and trade pieces.'],
          club='Many club Sicilian players never study 2.c3 and answer with natural moves like 2...d6 3.d4, which hands White the full center. Two lines (2...d5 and 2...Nf6) are all Black needs.'),
  ko=dict(name='알라핀 시실리안', title='알라핀 시실리안(2.c3): 수순·계획·레이팅별 응수',
          desc='알라핀 시실리안(1.e4 c5 2.c3) 정리: 2...d5, 2...Nf6와 다른 응수, 양쪽 계획, 레이팅별로 많이 두는 수.',
          lead='2.c3는 d4를 준비해서 폰으로 되잡고 중앙을 채우려는 수예요. 오픈 시실리안의 엄청난 이론을 피하고 배우기도 쉬워요.',
          white=['2...Nf6에는 3.e5 Nd5 4.d4 뒤 Nf3, Bc4나 Bd3로 전개해요.',
                 '2...d5에는 3.exd5 Qxd5 4.d4, 나중에 Nc3로 퀸을 쫓아요.',
                 'd4에 고립 폰이 자주 생겨요. 그 폰으로 말을 활발하게 써요.'],
          black=['2...d5와 2...Nf6가 가장 좋은 두 응수예요. 둘 다 d4가 오기 전에 e4를 쳐요.',
                 '두 갈래 모두 ...e6, ...Nc6, 알맞은 때의 ...cxd4가 흔해요.',
                 '백에게 고립 폰이 생기면 d5에서 막고 말을 바꿔요.'],
          club='동호인 시실리안 상당수는 2.c3를 공부하지 않아서 2...d6 3.d4 같은 자연스러운 수로 백에게 중앙을 다 내줘요. 흑은 두 갈래(2...d5, 2...Nf6)면 충분해요.'),
  vars=[V('e4 c5 c3 Nf6 e5 Nd5 d4 cxd4 Nf3', '2...Nf6 3.e5 Nd5', 'The main line. White builds a center; Black hits it with ...d6 or ...e6 and ...Nc6.',
          '2...Nf6 3.e5 Nd5', '주요 수순이에요. 백이 중앙을 쌓고 흑은 ...d6나 ...e6, ...Nc6로 쳐요.'),
        V('e4 c5 c3 d5 exd5 Qxd5 d4 Nf6 Nf3', '2...d5 3.exd5 Qxd5', 'Black’s queen is active early. White develops and aims for an isolated-pawn middlegame.',
          '2...d5 3.exd5 Qxd5', '흑 퀸이 일찍 활발해요. 백은 전개하며 고립 폰 중반으로 가요.'),
        V('e4 c5 c3 d6 d4', '2...d6 3.d4', 'White gets the ideal center. Playable for Black but less active.',
          '2...d6 3.d4', '백이 이상적인 중앙을 얻어요. 흑도 둘 만하지만 덜 활발해요.')],
  traps=[TR('e4 c5 Nf3 d6 c3 Nf6 Be2 Nxe4 Qa4+ Bd7 Qxe4', 'Delayed Alapin: 4...Nxe4?? 5.Qa4+',
            'After 2.Nf3 d6 3.c3 Nf6 4.Be2 the e4 pawn looks free, but 4...Nxe4?? 5.Qa4+ checks the king and hits the knight at the same time. Between 1200 and 1599 about one in three players take it, and White then scores about 80%.',
            '딜레이드 알라핀: 4...Nxe4?? 5.Qa4+', '2.Nf3 d6 3.c3 Nf6 4.Be2 뒤 e4 폰이 공짜처럼 보이지만, 4...Nxe4??에는 5.Qa4+가 킹 체크와 나이트 공격을 한 번에 해요. 1200~1599에서는 셋에 하나 정도가 이 폰을 먹고, 그 뒤 백 점수는 80% 정도예요.')])

O('sicilian-classical', 'b', 'sicilian', 'e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 Nc6',
  ['Sicilian Defense: Classical Variation', 'Sicilian Defense: Richter-Rauzer Variation', 'Sicilian Defense: Sozin Attack',
   'Sicilian Defense: Velimirovic Attack', 'Sicilian Defense: Boleslavsky Variation'],
  en=dict(name='Sicilian Classical', title='Sicilian Classical (5...Nc6): Richter-Rauzer, Sozin and Stats',
          desc='The Classical Sicilian (5...Nc6): the Richter-Rauzer 6.Bg5, the Sozin 6.Bc4, 6.Be3 Ng4 and 6.Be2 e5, with plans and how often each is played.',
          lead='5...Nc6 is the most natural move in the Open Sicilian: the knight goes to its best square and hits d4. Black keeps the choice between ...e6, ...e5 and ...g6 for one more move, so White has to decide how to fight first.',
          white=['6.Bg5 (Richter-Rauzer) is the main line: after 6...e6 7.Qd2 White castles long and puts pressure on d6 and f6.',
                 '6.Bc4 (Sozin) aims the bishop at e6 and f7. With Be3, Qe2 and O-O-O it becomes the very sharp Velimirovic Attack.',
                 '6.Be3 is popular too, but 6...Ng4 hits the bishop at once. Answer it with 7.Bb5 or 7.Bg5.'],
          black=['Against 6.Bg5, 6...e6 with ...a6, ...Bd7 and ...Be7 is the main line. If White takes on f6, recapture with the g-pawn and use the bishop pair.',
                 'Against 6.Bc4, 6...e6 blunts the bishop, or 6...Qb6 (Benko) chases the d4 knight first.',
                 'After 6.Nxc6 bxc6 your center gets stronger: aim for ...e5 or ...d5 and use the half-open b-file.'],
          club='At 2000+ a third of players answer with 6.Bg5, and nearly half meet 6.Be3 with 6...Ng4, after which White scores only about 41%. Between 1200 and 1599 the most common move is 6.Bb5, and below 1200 it is 6.Nxc6. After 6.Nxc6 bxc6 White scores about 47%, so that trade helps Black.'),
  ko=dict(name='시실리안 클래시컬', title='시실리안 클래시컬(5...Nc6): 리히터-라우저·소진, 레이팅별 응수',
          desc='클래시컬 시실리안(5...Nc6) 정리: 리히터-라우저 6.Bg5, 소진 6.Bc4, 6.Be3 Ng4, 6.Be2 e5, 양쪽 계획과 레이팅별로 많이 두는 수.',
          lead='5...Nc6는 오픈 시실리안에서 가장 자연스러운 수예요. 나이트가 제자리로 가서 d4를 쳐요. 흑은 ...e6, ...e5, ...g6 중 무엇을 둘지 한 수 더 미룰 수 있어서, 백이 먼저 싸우는 방법을 정해야 해요.',
          white=['6.Bg5(리히터-라우저)가 주요 수순이에요. 6...e6 7.Qd2 뒤 긴 캐슬링을 하고 d6와 f6를 압박해요.',
                 '6.Bc4(소진)는 비숍으로 e6·f7을 겨눠요. Be3, Qe2, O-O-O까지 가면 아주 날카로운 벨리미로비치 어택이에요.',
                 '6.Be3도 많이 두지만 6...Ng4가 바로 비숍을 쳐요. 7.Bb5나 7.Bg5로 받아요.'],
          black=['6.Bg5에는 6...e6 뒤 ...a6, ...Bd7, ...Be7가 주요 수순이에요. 백이 f6에서 바꾸면 g폰으로 되잡고 비숍 쌍을 써요.',
                 '6.Bc4에는 6...e6로 비숍을 막거나, 6...Qb6(벤코)로 d4 나이트부터 쫓아요.',
                 '6.Nxc6 bxc6 뒤엔 흑 중앙이 더 단단해져요. ...e5나 ...d5를 노리고 반쯤 열린 b파일을 써요.'],
          club='2000 이상에서는 셋에 하나가 6.Bg5를 두고, 6.Be3에는 절반 가까이가 6...Ng4로 받아요. 그 뒤 백 점수는 41% 정도예요. 1200~1599에서는 6.Bb5, 1200 미만에서는 6.Nxc6가 가장 많아요. 6.Nxc6 bxc6 뒤 백 점수는 47% 정도라서 이 교환은 흑에게 더 좋아요.'),
  vars=[V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 Nc6 Bg5 e6 Qd2 a6 O-O-O Bd7 f4 b5', 'Richter-Rauzer, 6.Bg5 e6 7.Qd2', 'White castles long and pushes f4–f5 or e5; Black races with ...b5–b4.',
          '리히터-라우저, 6.Bg5 e6 7.Qd2', '백은 긴 캐슬링 뒤 f4–f5나 e5를 밀고, 흑은 ...b5–b4로 경주해요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 Nc6 Bc4 e6 Be3 Be7 Qe2 a6 O-O-O', 'Sozin and Velimirovic Attack', 'The bishop hits e6, the queen goes to e2 and White castles long to push g4–g5.',
          '소진과 벨리미로비치 어택', '비숍이 e6를 치고, 퀸은 e2로 가고, 긴 캐슬링 뒤 g4–g5를 밀어요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 Nc6 Bc4 Qb6 Nb3 e6', 'Benko, 6.Bc4 Qb6', 'Black pushes the knight back from d4 before the Sozin setup is complete.',
          '벤코, 6.Bc4 Qb6', '소진 배치가 끝나기 전에 d4 나이트를 먼저 물려요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 Nc6 Be3 Ng4 Bb5 Nxe3 fxe3', '6.Be3 Ng4', 'Black wins the bishop pair; White gets the half-open f-file and quick development.',
          '6.Be3 Ng4', '흑이 비숍 쌍을 얻고, 백은 반쯤 열린 f파일과 빠른 전개를 얻어요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 Nc6 Be2 e5 Nb3 Be7', 'Boleslavsky, 6.Be2 e5', 'Black takes space with ...e5 and accepts the hole on d5, as in the Najdorf.',
          '볼레슬랍스키, 6.Be2 e5', '흑이 ...e5로 공간을 잡고, 나이도르프처럼 d5 구멍을 받아들여요.')],
  traps=[])

O('sicilian-scheveningen', 'b', 'sicilian', 'e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 e6', ['Sicilian Defense: Scheveningen Variation'],
  en=dict(name='Sicilian Scheveningen', title='Sicilian Scheveningen: Keres Attack, English Attack and Stats',
          desc='The Scheveningen Sicilian (5...e6): the small center, the Keres Attack 6.g4, the English Attack and the quiet 6.Be2, with how often each is played.',
          lead='5...e6 builds a small center with pawns on d6 and e6. Together they cover c5, d5, e5 and f5, so White’s pieces have no easy squares. The price is a little less space and a kingside pawn storm to survive later.',
          white=['6.g4 (Keres Attack) is the most direct: the pawn chases the f6 knight before Black can castle.',
                 '6.Be3 with f3, Qd2 and O-O-O (English Attack) is the modern way: castle long and storm with g4–g5.',
                 '6.Be2 with O-O and f4 is the classical plan, slower but solid.'],
          black=['Typical setup: ...a6, ...Qc7, ...Be7, ...Nc6 or ...Nbd7, and ...O-O at the right moment.',
                 'Against 6.g4, 6...h6 is the main answer: it slows g5 down.',
                 'Your breaks are ...d5 and ...e5 in the center and ...b5–b4 on the queenside.'],
          club='At 2000+ the Keres Attack 6.g4 and 6.Be3 are equally common, about one in five each. Below 2000, 6.Bg5 is the most common move, and below 1600 about one in six check with 6.Bb5+. White scores only about 43% after 6.Bb5+, so it is nothing to fear.'),
  ko=dict(name='시실리안 셰베닝겐', title='시실리안 셰베닝겐: 케레스 어택·잉글리시 어택, 레이팅별 응수',
          desc='셰베닝겐 시실리안(5...e6) 정리: 작은 중앙, 케레스 어택 6.g4, 잉글리시 어택, 조용한 6.Be2, 레이팅별로 많이 두는 수.',
          lead='5...e6로 d6·e6에 작은 중앙을 세워요. 두 폰이 c5, d5, e5, f5를 막아서 백 말이 자리 잡을 곳이 마땅치 않아요. 대신 공간이 조금 좁고, 나중에 킹 쪽 폰 폭풍을 견뎌야 해요.',
          white=['6.g4(케레스 어택)가 가장 직접적이에요. 흑이 캐슬링하기 전에 폰으로 f6 나이트를 쫓아요.',
                 '6.Be3와 f3, Qd2, O-O-O(잉글리시 어택)가 요즘 방식이에요. 긴 캐슬링 뒤 g4–g5로 밀어요.',
                 '6.Be2와 O-O, f4는 클래시컬 계획이에요. 느리지만 단단해요.'],
          black=['흔한 배치: ...a6, ...Qc7, ...Be7, ...Nc6나 ...Nbd7, 알맞은 때 ...O-O.',
                 '6.g4에는 6...h6가 주요 응수예요. g5를 늦춰요.',
                 '돌파는 중앙의 ...d5·...e5, 퀸 쪽의 ...b5–b4예요.'],
          club='2000 이상에서는 케레스 어택 6.g4와 6.Be3가 다섯에 하나꼴로 똑같이 많아요. 2000 아래에서는 6.Bg5가 가장 많고, 1600 아래에서는 여섯에 하나 정도가 6.Bb5+로 체크해요. 6.Bb5+ 뒤 백 점수는 43% 정도라서 겁낼 필요 없어요.'),
  vars=[V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 e6 g4 h6 h4 Nc6 Rg1', 'Keres Attack, 6.g4', 'White grabs kingside space at once. After 6...h6 the pawn needs h4 and Rg1 behind it to go on.',
          '케레스 어택, 6.g4', '백이 바로 킹 쪽 공간을 잡아요. 6...h6 뒤엔 h4와 Rg1로 받쳐야 더 밀 수 있어요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 e6 Be3 a6 f3 b5 Qd2', 'English Attack, 6.Be3', 'Opposite-side castling: White castles long and pushes g4; Black answers with ...b5–b4.',
          '잉글리시 어택, 6.Be3', '반대쪽 캐슬링 판이에요. 백은 긴 캐슬링과 g4, 흑은 ...b5–b4로 맞서요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 e6 Be2 Be7 O-O O-O f4', 'Classical, 6.Be2', 'Both sides castle short. White prepares Be3 and a kingside push; Black plays ...a6, ...Qc7 and ...Nc6.',
          '클래시컬, 6.Be2', '둘 다 짧은 캐슬링을 해요. 백은 Be3와 킹 쪽 밀기를, 흑은 ...a6, ...Qc7, ...Nc6를 둬요.'),
        V('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 e6 Bg5 Be7', '6.Bg5', 'The most common move below 2000. After 6...Be7 the pin is harmless.',
          '6.Bg5', '2000 아래에서 가장 많은 수예요. 6...Be7로 전개하면 핀은 별것 아니에요.')],
  traps=[])

O('sicilian-sveshnikov', 'b', 'sicilian', 'e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5',
  ['Sicilian Defense: Lasker-Pelikan Variation', 'Sicilian Defense: Löwenthal Variation', 'Sicilian Defense: Kalashnikov Variation'],
  en=dict(name='Sicilian Sveshnikov', title='Sicilian Sveshnikov and Kalashnikov: Lines and Stats by Rating',
          desc='The Sveshnikov Sicilian (5...e5) and the Kalashnikov and Löwenthal (4...e5): the d5 hole, 9.Bxf6 and 9.Nd5, and reply rates by rating.',
          lead='5...e5 kicks the d4 knight at once and grabs space, at the cost of a lasting hole on d5 and a backward d-pawn. Active pieces make up for it, which is why the Sveshnikov is a favorite of top players, Magnus Carlsen among them.',
          white=['6.Ndb5 is the main move: the knight eyes d6, and after 6...d6 7.Bg5 a6 8.Na3 b5 the fight is all about d5.',
                 '9.Bxf6 gxf6 10.Nd5 breaks up Black’s kingside pawns; 9.Nd5 keeps it quieter.',
                 'A knight on d5 that cannot be traded is White’s dream. Trade off the black pieces that can cover d5.'],
          black=['After 6.Ndb5 play 6...d6: the knight must not land on d6.',
                 'Your plan is ...f5 to hit e4, and ...Bg5 or ...Bg7 to trade or activate the bad bishop.',
                 'The Kalashnikov (4...e5 5.Nb5 d6) is the same idea a move earlier, without ...Nf6.'],
          club='Below 1600 the most common answer to 5...e5 is 6.Nxc6, and below 1200 three in four answer 4...e5 with 5.Nxc6. After 5...e5 6.Nxc6 bxc6 White scores only about 48%. At 2000+ four in five play 6.Ndb5, so that is the line to learn first.'),
  ko=dict(name='시실리안 스베시니코프', title='시실리안 스베시니코프·칼라시니코프: 수순과 레이팅별 응수',
          desc='스베시니코프 시실리안(5...e5)과 칼라시니코프·뢰벤탈(4...e5) 정리: d5 구멍, 9.Bxf6와 9.Nd5, 레이팅별 응수 비율.',
          lead='5...e5는 d4 나이트를 바로 쫓고 공간을 잡아요. 대신 d5에 오래가는 구멍이 생기고 d폰이 뒤처져요. 기물이 활발해서 그 값을 하고, 그래서 망누스 칼센 같은 최정상 선수들이 즐겨 둬요.',
          white=['6.Ndb5가 주요 수예요. 나이트가 d6를 노리고, 6...d6 7.Bg5 a6 8.Na3 b5 뒤에는 d5를 두고 싸워요.',
                 '9.Bxf6 gxf6 10.Nd5는 흑 킹 쪽 폰을 흩뜨리고, 9.Nd5는 더 조용해요.',
                 '바꿀 수 없는 d5 나이트가 백의 꿈이에요. d5를 지킬 수 있는 흑 말을 바꿔 없애요.'],
          black=['6.Ndb5에는 6...d6. 나이트가 d6에 들어오면 안 돼요.',
                 '흑의 계획은 ...f5로 e4를 치고, ...Bg5나 ...Bg7로 나쁜 비숍을 바꾸거나 살리는 거예요.',
                 '칼라시니코프(4...e5 5.Nb5 d6)는 ...Nf6 없이 한 수 먼저 같은 생각을 해요.'],
          club='1600 아래에서는 5...e5에 6.Nxc6가 가장 많고, 1200 미만에서는 넷에 셋이 4...e5에 5.Nxc6로 바꿔요. 5...e5 6.Nxc6 bxc6 뒤 백 점수는 48% 정도예요. 2000 이상에서는 다섯에 넷이 6.Ndb5를 두니까 그 갈래부터 익히세요.'),
  vars=[V('e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5 Ndb5 d6 Bg5 a6 Na3 b5 Bxf6 gxf6 Nd5 f5', 'Main line, 9.Bxf6 gxf6 10.Nd5 f5', 'Black’s pawns look broken, but the bishop pair and ...f5 give real counterplay.',
          '주요 수순, 9.Bxf6 gxf6 10.Nd5 f5', '흑 폰은 망가져 보이지만 비숍 쌍과 ...f5로 충분히 반격해요.'),
        V('e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5 Ndb5 d6 Bg5 a6 Na3 b5 Nd5 Be7', '9.Nd5', 'White keeps the bishop and trades on f6 only when it helps.',
          '9.Nd5', '백이 비숍을 남기고, 도움이 될 때만 f6에서 바꿔요.'),
        V('e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5 Ndb5 d6 Nd5 Nxd5 exd5', '7.Nd5', 'White trades at once and gains space; the d5 pawn blocks Black’s center.',
          '7.Nd5', '백이 바로 바꿔서 공간을 얻어요. d5 폰이 흑 중앙을 막아요.'),
        V('e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 e5 Nb5 d6 N1c3 a6 Na3 b5 Nd5', 'Kalashnikov, 4...e5 5.Nb5 d6', 'The same d5 fight before ...Nf6; White can also clamp d5 with 6.c4.',
          '칼라시니코프, 4...e5 5.Nb5 d6', '...Nf6 전에 같은 d5 싸움을 해요. 백은 6.c4로 d5를 죄기도 해요.'),
        V('e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 e5 Nb5 a6 Nd6+ Bxd6 Qxd6 Qf6', 'Löwenthal, 4...e5 5.Nb5 a6', 'Black gives up the dark-squared bishop for fast development.',
          '뢰벤탈, 4...e5 5.Nb5 a6', '흑이 검은 칸 비숍을 내주고 빠른 전개를 얻어요.'),
        V('e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5 Nxc6 bxc6', 'Exchange, 6.Nxc6', 'Common below 1600. Black’s center gets stronger and ...d5 comes soon.',
          '익스체인지, 6.Nxc6', '1600 아래에서 흔해요. 흑 중앙이 더 단단해지고 곧 ...d5가 나와요.')],
  traps=[])

O('sicilian-taimanov', 'b', 'sicilian', 'e4 c5 Nf3 e6 d4 cxd4 Nxd4 Nc6',
  ['Sicilian Defense: Taimanov Variation', 'Sicilian Defense: Four Knights Variation'],
  en=dict(name='Sicilian Taimanov', title='Sicilian Taimanov (4...Nc6): Lines, Plans and Stats by Rating',
          desc='The Taimanov Sicilian (2...e6 and 4...Nc6): 5.Nc3 Qc7, 5...a6, the Four Knights 5...Nf6 and 5.Nb5, with plans and how often each is played.',
          lead='4...Nc6 develops a knight and keeps everything flexible. Black has not committed to ...d6 or ...Nf6 yet, so the pieces can go wherever White leaves room: ...Qc7, ...a6 and ...Nf6, or a quick ...Bb4.',
          white=['5.Nc3 is the main move. Against 5...Qc7 the English Attack with Be3, Qd2 and O-O-O is the sharpest plan.',
                 '5.Nb5 hits d6 and asks Black for ...d6, a Scheveningen-like structure where c4 clamps the center.',
                 '5.Nxc6 bxc6 is simple but helps Black: the b-pawn comes to c6 and backs up ...d5.'],
          black=['5...a6 keeps the knight off b5; after 5...Qc7 the queen covers d6, and 6.Ndb5 is met by 6...Qb8. Both prepare ...Nf6 and ...Bb4.',
                 '5...Nf6 is the Four Knights. After 6.Ndb5 play 6...Bb4 or 6...d6; 6.Nxc6 bxc6 7.e5 Nd5 is the other main line.',
                 'The ...d5 break is your main freeing move; prepare it with ...Nf6 and ...Bb4.'],
          club='Below 1200 half the players answer 4...Nc6 with 5.Nxc6, and between 1200 and 1599 it is still just ahead of 5.Nc3 (37% to 36%). After 5.Nxc6 bxc6 White scores only about 48%. At 2000+ six in ten play 5.Nc3.'),
  ko=dict(name='시실리안 타이마노프', title='시실리안 타이마노프(4...Nc6): 수순·계획·레이팅별 응수',
          desc='타이마노프 시실리안(2...e6, 4...Nc6) 정리: 5.Nc3 Qc7, 5...a6, 포 나이츠 5...Nf6, 5.Nb5, 양쪽 계획과 레이팅별로 많이 두는 수.',
          lead='4...Nc6는 나이트를 전개하면서 모든 걸 유연하게 남겨요. 흑은 아직 ...d6나 ...Nf6를 정하지 않아서, 백이 비워 둔 곳으로 말을 보내요. ...Qc7, ...a6, ...Nf6, 또는 빠른 ...Bb4.',
          white=['5.Nc3가 주요 수예요. 5...Qc7에는 Be3, Qd2, O-O-O(잉글리시 어택)가 가장 날카로워요.',
                 '5.Nb5는 d6를 노려 흑에게 ...d6를 강요해요. 셰베닝겐 비슷한 구조에서 c4로 중앙을 죄어요.',
                 '5.Nxc6 bxc6는 단순하지만 흑을 도와요. b폰이 c6로 와서 ...d5를 받쳐요.'],
          black=['5...a6는 나이트가 b5에 못 오게 해요. 5...Qc7는 퀸이 d6를 지키고, 6.Ndb5에는 6...Qb8로 피해요. 둘 다 ...Nf6와 ...Bb4를 준비해요.',
                 '5...Nf6가 포 나이츠예요. 6.Ndb5에는 6...Bb4나 6...d6, 그리고 6.Nxc6 bxc6 7.e5 Nd5가 또 다른 주요 수순이에요.',
                 '...d5 돌파가 판을 푸는 주된 수예요. ...Nf6와 ...Bb4로 준비해요.'],
          club='1200 미만에서는 절반이 4...Nc6에 5.Nxc6로 바꾸고, 1200~1599에서도 5.Nxc6가 5.Nc3보다 조금 많아요(37% 대 36%). 5.Nxc6 bxc6 뒤 백 점수는 48% 정도예요. 2000 이상에서는 열에 여섯이 5.Nc3를 둬요.'),
  vars=[V('e4 c5 Nf3 e6 d4 cxd4 Nxd4 Nc6 Nc3 Qc7 Be3 a6 Qd2 Nf6 O-O-O', 'English Attack, 5...Qc7 6.Be3', 'White castles long; Black plays ...Bb4 or ...b5 and goes after the king on the queenside.',
          '잉글리시 어택, 5...Qc7 6.Be3', '백은 긴 캐슬링, 흑은 ...Bb4나 ...b5로 퀸 쪽에서 킹을 노려요.'),
        V('e4 c5 Nf3 e6 d4 cxd4 Nxd4 Nc6 Nc3 Nf6 Ndb5 Bb4 a3 Bxc3+ Nxc3 d5', 'Four Knights, 6.Ndb5 Bb4', 'Black gives the bishop for the knight and breaks with ...d5 at once.',
          '포 나이츠, 6.Ndb5 Bb4', '흑이 비숍을 나이트와 바꾸고 바로 ...d5로 돌파해요.'),
        V('e4 c5 Nf3 e6 d4 cxd4 Nxd4 Nc6 Nc3 Nf6 Nxc6 bxc6 e5 Nd5 Ne4', 'Four Knights, 6.Nxc6 bxc6 7.e5', 'White gains space with e5; Black hits the pawn with ...Qc7 and ...f6 or ...d6.',
          '포 나이츠, 6.Nxc6 bxc6 7.e5', '백이 e5로 공간을 잡고, 흑은 ...Qc7와 ...f6나 ...d6로 그 폰을 쳐요.'),
        V('e4 c5 Nf3 e6 d4 cxd4 Nxd4 Nc6 Nb5 d6 c4 Nf6 N1c3', '5.Nb5 d6 6.c4', 'Pawns on c4 and e4 hold d5. Black sets up with ...a6, ...Be7 and ...O-O and waits for ...b5 or ...d5.',
          '5.Nb5 d6 6.c4', 'c4·e4 폰이 d5를 막아요. 흑은 ...a6, ...Be7, ...O-O로 웅크리고 ...b5나 ...d5를 노려요.')],
  traps=[])

O('sicilian-kan', 'b', 'sicilian', 'e4 c5 Nf3 e6 d4 cxd4 Nxd4 a6', ['Sicilian Defense: Kan Variation'],
  en=dict(name='Sicilian Kan', title='Sicilian Kan (4...a6): Maróczy Bind, 5.Bd3 and Stats by Rating',
          desc='The Kan Sicilian (2...e6 and 4...a6): 5.Nc3 Qc7, 5.Bd3, the Maróczy Bind with 5.c4 and the Hedgehog setup, with how often each is played.',
          lead='4...a6 is the most flexible move in the Sicilian. It takes b5 away from White’s pieces and keeps every option open: ...Qc7, ...b5, ...Nf6, ...Bc5 or ...d6. Black waits to see White’s setup before choosing a structure.',
          white=['5.Nc3 is the most common move; after 5...Qc7 develop with Bd3 or Be3 and castle.',
                 '5.Bd3 covers e4 with a piece and keeps the c-pawn free to go to c4.',
                 '5.c4 is the Maróczy Bind: pawns on c4 and e4 grip d5 and leave Black cramped.'],
          black=['...Qc7 covers e5 and c5. Against 5.Nc3 it is the most common reply at every rating.',
                 'Against 5.c4 play the Hedgehog: ...Nf6, ...Qc7, ...b6, ...Bb7 and ...d6, then wait for ...b5 or ...d5.',
                 'Against 5.Bd3, ...Bc5 or ...Nf6 with ...Qc7 develops quickly.'],
          club='The Kan scores well for Black: White averages only about 48% after 4...a6, and about 46% between 1600 and 1999. At 2000+ the Maróczy Bind 5.c4 is White’s second choice (27%), so learn the Hedgehog setup before you play the Kan against strong players.'),
  ko=dict(name='시실리안 칸', title='시실리안 칸(4...a6): 마로치 바인드·5.Bd3, 레이팅별 응수',
          desc='칸 시실리안(2...e6, 4...a6) 정리: 5.Nc3 Qc7, 5.Bd3, 5.c4 마로치 바인드와 고슴도치 배치, 레이팅별로 많이 두는 수.',
          lead='4...a6는 시실리안에서 가장 유연한 수예요. 백 말이 b5에 못 오게 하고 ...Qc7, ...b5, ...Nf6, ...Bc5, ...d6 중 무엇이든 남겨 둬요. 흑은 백 배치를 보고 나서 구조를 골라요.',
          white=['5.Nc3가 가장 많아요. 5...Qc7 뒤 Bd3나 Be3로 전개하고 캐슬링해요.',
                 '5.Bd3는 e4를 말로 지키고 c폰을 c4로 밀 수 있게 남겨요.',
                 '5.c4가 마로치 바인드예요. c4·e4 폰이 d5를 쥐어 흑이 답답해져요.'],
          black=['...Qc7는 e5와 c5를 지켜요. 5.Nc3에는 모든 레이팅대에서 가장 흔한 응수예요.',
                 '5.c4에는 고슴도치 배치: ...Nf6, ...Qc7, ...b6, ...Bb7, ...d6로 웅크리고 ...b5나 ...d5를 기다려요.',
                 '5.Bd3에는 ...Bc5나 ...Nf6와 ...Qc7로 빨리 전개해요.'],
          club='칸은 흑 성적이 좋아요. 4...a6 뒤 백 평균 점수는 48% 정도이고, 1600~1999에서는 46% 정도예요. 2000 이상에서는 5.c4 마로치 바인드가 백의 두 번째 선택(27%)이니, 강한 상대에게 칸을 두려면 고슴도치 배치부터 익히세요.'),
  vars=[V('e4 c5 Nf3 e6 d4 cxd4 Nxd4 a6 Nc3 Qc7 Bd3 Nc6 Be3 Nf6 O-O', '5.Nc3 Qc7', 'The main line. Black can switch to a Taimanov with ...Nc6 or play ...b5 and ...Bb7.',
          '5.Nc3 Qc7', '주요 수순이에요. 흑은 ...Nc6로 타이마노프처럼 가거나 ...b5와 ...Bb7를 둬요.'),
        V('e4 c5 Nf3 e6 d4 cxd4 Nxd4 a6 Bd3 Bc5 Nb3 Be7', 'Polugaevsky, 5.Bd3 Bc5', 'The bishop hits d4 at once; after 6.Nb3 it drops back to e7 or a7.',
          '폴루가옙스키, 5.Bd3 Bc5', '비숍이 바로 d4를 쳐요. 6.Nb3 뒤엔 e7이나 a7로 물러나요.'),
        V('e4 c5 Nf3 e6 d4 cxd4 Nxd4 a6 c4 Nf6 Nc3 Qc7 a3 b6 Be2 Bb7', 'Maróczy Bind, 5.c4', 'The Hedgehog: Black stays compact behind pawns on a6, b6, d6 and e6 and waits for ...b5 or ...d5.',
          '마로치 바인드, 5.c4', '고슴도치 배치예요. 흑은 a6, b6, d6, e6 폰 뒤에 웅크리고 ...b5나 ...d5를 기다려요.'),
        V('e4 c5 Nf3 e6 d4 cxd4 Nxd4 a6 Nc3 b5 Bd3 Qb6', 'Wing Attack, 5...b5', 'Black grabs queenside space at once and puts the bishop on b7.',
          '윙 어택, 5...b5', '흑이 바로 퀸 쪽 공간을 잡고 비숍을 b7에 놔요.')],
  traps=[])

O('closed-sicilian', 'w', 'sicilian', 'e4 c5 Nc3',
  ['Sicilian Defense: Closed', 'Sicilian Defense: Grand Prix Attack', 'Sicilian Defense: McDonnell Attack'],
  en=dict(name='Closed Sicilian', title='Closed Sicilian and Grand Prix Attack: Lines and Stats by Rating',
          desc='The Closed Sicilian (2.Nc3) with g3 and Bg2, the Grand Prix Attack with f4, and 2.f4: plans for both sides and how often each is played.',
          lead='2.Nc3 keeps the d-pawn at home and, unless White plays d4 later, avoids Open Sicilian theory. White builds slowly with g3, Bg2, d3 and f4, or goes straight for the king with f4, Nf3 and Bc4 or Bb5 in the Grand Prix Attack.',
          white=['Traditional setup: g3, Bg2, d3, Be3, Qd2 and f4–f5 on the kingside.',
                 'Grand Prix Attack: f4, Nf3 and Bb5 or Bc4, then O-O and a kingside attack with Qe1–h4.',
                 'Keep the center closed; your attack works best when Black cannot hit back with ...d5.'],
          black=['2...Nc6 is the most common reply at every rating; ...g6, ...Bg7 and ...d6 mirror White’s setup.',
                 'Your play is on the queenside: ...Rb8, ...b5–b4 and pressure down the long diagonal.',
                 'Against the Grand Prix, ...e6 and ...d5 at the right moment blunt the c4 bishop.'],
          club='Below 1200 about half the players answer 2...Nc6 with 3.Nf3, which often turns into an Open Sicilian after d4. At 2000+, 3.f4 (Grand Prix, 29%) and 3.g3 (Closed, 24%) lead. Against 3.f4, half of the 2000+ players choose 3...g6.'),
  ko=dict(name='클로즈드 시실리안', title='클로즈드 시실리안·그랑프리 어택: 수순과 레이팅별 응수',
          desc='클로즈드 시실리안(2.Nc3)의 g3·Bg2 배치, f4로 가는 그랑프리 어택, 2.f4까지, 양쪽 계획과 레이팅별로 많이 두는 수.',
          lead='2.Nc3는 d폰을 집에 두고, 나중에 d4를 두지 않는 한 오픈 시실리안 이론을 피해요. 백은 g3, Bg2, d3, f4로 천천히 쌓거나, 그랑프리 어택처럼 f4, Nf3, Bc4나 Bb5로 바로 킹을 노려요.',
          white=['전통 배치: g3, Bg2, d3, Be3, Qd2, 킹 쪽에서 f4–f5.',
                 '그랑프리 어택: f4, Nf3, Bb5나 Bc4, 그다음 O-O와 Qe1–h4로 킹 쪽 공격.',
                 '중앙을 닫아 둬요. 흑이 ...d5로 맞받아칠 수 없을 때 공격이 가장 잘 돼요.'],
          black=['2...Nc6가 모든 레이팅대에서 가장 많아요. ...g6, ...Bg7, ...d6로 백 배치를 거울처럼 따라 해요.',
                 '흑의 판은 퀸 쪽이에요: ...Rb8, ...b5–b4, 긴 대각선 압박.',
                 '그랑프리에는 알맞은 때 ...e6와 ...d5로 c4 비숍을 막아요.'],
          club='1200 미만에서는 절반 정도가 2...Nc6에 3.Nf3를 두고, 나중에 d4로 오픈 시실리안이 되는 일이 많아요. 2000 이상에서는 3.f4(그랑프리, 29%)와 3.g3(클로즈드, 24%)가 앞서요. 3.f4에는 2000 이상의 절반이 3...g6를 둬요.'),
  vars=[V('e4 c5 Nc3 Nc6 g3 g6 Bg2 Bg7 d3 d6 Be3 Rb8 Qd2 b5', 'Traditional Closed, 3.g3', 'Both sides fianchetto. White prepares f4–f5 or Bh6; Black pushes the b-pawn.',
          '전통 클로즈드, 3.g3', '둘 다 피앙케토를 해요. 백은 f4–f5나 Bh6를 준비하고, 흑은 b폰을 밀어요.'),
        V('e4 c5 Nc3 Nc6 g3 g6 Bg2 Bg7 d3 d6 f4 e5', 'Botvinnik setup, 6...e5', 'Black fixes the center with pawns on c5, d6 and e5 and takes control of d4.',
          '보트비닉 배치, 6...e5', '흑이 c5, d6, e5 폰으로 중앙을 고정하고 d4를 차지해요.'),
        V('e4 c5 Nc3 Nc6 f4 g6 Nf3 Bg7 Bb5 Nd4', 'Grand Prix, 3.f4 g6', 'White’s bishop goes to b5 or c4; ...Nd4 is a common answer to Bb5.',
          '그랑프리, 3.f4 g6', '백 비숍은 b5나 c4로 가요. Bb5에는 ...Nd4가 흔한 응수예요.'),
        V('e4 c5 Nc3 Nc6 f4 e6 Nf3 d5', 'Grand Prix, 3.f4 e6', 'Black strikes in the center with ...d5 before White can attack.',
          '그랑프리, 3.f4 e6', '백이 공격하기 전에 흑이 ...d5로 중앙을 쳐요.'),
        V('e4 c5 f4 d5', 'McDonnell Attack, 2.f4', 'f4 one move early, without Nc3. At 2000+ about one in five answer 2...d5.',
          '맥도넬 어택, 2.f4', 'Nc3 없이 f4를 한 수 먼저 둬요. 2000 이상에서는 다섯에 하나 정도가 2...d5로 받아요.')],
  traps=[])

O('rossolimo-attack', 'w', 'sicilian', 'e4 c5 Nf3 Nc6 Bb5', ['Sicilian Defense: Nyezhmetdinov-Rossolimo Attack'],
  en=dict(name='Rossolimo Attack', title='Rossolimo Attack (3.Bb5): Lines, Plans and Stats by Rating',
          desc='The Rossolimo (1.e4 c5 2.Nf3 Nc6 3.Bb5): 3...g6, 3...e6 and 3...d6, when to take on c6, plans for both sides and how often each is played.',
          lead='3.Bb5 threatens to take on c6 and double Black’s pawns. White avoids the Open Sicilian, castles quickly and plays for a small but lasting edge. Many top players use it against 2...Nc6.',
          white=['Bxc6 is often the point: doubled c-pawns and a slow game where your knights can outplay Black’s bishops.',
                 'O-O, Re1 and c3 with d4 is the other plan, keeping the bishop for now.',
                 'Against 3...g6, 4.Bxc6 dxc6 5.d3 with h3, Nc3 and Be3 is a well-known setup.'],
          black=['3...g6 is the most common answer at 2000+: the bishop goes to g7, where it backs up the c5 pawn’s hold on d4 and eyes the long diagonal.',
                 'After Bxc6 you can take back with ...bxc6 toward the center or ...dxc6 to free your pieces; both are playable.',
                 '3...e6 prepares ...Nge7 so that a knight can take back on c6.'],
          club='Below 1200 the most common answer to 3.Bb5 is 3...a6, asking the bishop to decide at once. At 2000+ a third choose 3...g6, and after it half see 4.O-O and over a third 4.Bxc6. Below 2000 White takes on c6 more often than castling there.'),
  ko=dict(name='로솔리모 어택', title='로솔리모 어택(3.Bb5): 수순·계획·레이팅별 응수',
          desc='로솔리모(1.e4 c5 2.Nf3 Nc6 3.Bb5) 정리: 3...g6, 3...e6, 3...d6, c6에서 바꿀 때, 양쪽 계획과 레이팅별로 많이 두는 수.',
          lead='3.Bb5는 c6에서 바꿔 흑 폰을 겹치게 만들겠다고 위협해요. 백은 오픈 시실리안을 피하고, 빨리 캐슬링한 뒤 작지만 오래가는 우세를 노려요. 2...Nc6를 상대로 최정상 선수들도 많이 써요.',
          white=['Bxc6가 핵심인 경우가 많아요. c폰이 겹치고 느린 판이 되면 백 나이트가 흑 비숍보다 나을 수 있어요.',
                 'O-O, Re1, c3와 d4로 비숍을 당분간 남겨 두는 계획도 있어요.',
                 '3...g6에는 4.Bxc6 dxc6 5.d3 뒤 h3, Nc3, Be3로 가는 배치가 잘 알려져 있어요.'],
          black=['2000 이상에서는 3...g6가 가장 많아요. 비숍이 g7로 가서 c5 폰과 함께 d4를 누르고 긴 대각선을 겨눠요.',
                 'Bxc6 뒤엔 중앙 쪽으로 ...bxc6도, 말길을 여는 ...dxc6도 둘 만해요.',
                 '3...e6는 ...Nge7를 준비해서 c6를 나이트로 되잡을 수 있게 해요.'],
          club='1200 미만에서는 3.Bb5에 3...a6가 가장 많아요. 비숍에게 바로 정하라는 수예요. 2000 이상에서는 셋에 하나가 3...g6를 두고, 그 뒤 절반은 4.O-O, 셋에 하나 넘게는 4.Bxc6를 봐요. 2000 아래 백은 거기서 캐슬링보다 c6에서 바꾸는 쪽이 더 많아요.'),
  vars=[V('e4 c5 Nf3 Nc6 Bb5 g6 Bxc6 dxc6 d3 Bg7 h3 Nf6 Nc3', '3...g6 4.Bxc6 dxc6', 'White gives up the bishop pair to slow the game down; the plan is Be3, Qd2 and Bh6 to trade the g7 bishop.',
          '3...g6 4.Bxc6 dxc6', '백이 비숍 쌍을 내주고 판을 느리게 해요. Be3, Qd2, Bh6로 g7 비숍을 바꾸는 계획이에요.'),
        V('e4 c5 Nf3 Nc6 Bb5 g6 O-O Bg7 Re1 e5', '3...g6 4.O-O', 'White keeps the bishop; ...e5 and ...Nf6 are the main answers to 5.Re1.',
          '3...g6 4.O-O', '백이 비숍을 남겨요. 5.Re1에는 ...e5와 ...Nf6가 주요 응수예요.'),
        V('e4 c5 Nf3 Nc6 Bb5 e6 O-O Nge7 Re1 a6 Bf1', '3...e6', 'Black prepares ...Nge7 to recapture on c6 with a piece; White often keeps the bishop with Bf1.',
          '3...e6', '흑이 ...Nge7로 c6를 말로 되잡으려 해요. 백은 Bf1로 비숍을 남기기도 해요.'),
        V('e4 c5 Nf3 Nc6 Bb5 d6 O-O Bd7 Re1 Nf6 c3 a6 Bf1', '3...d6', 'Also reached from 2...d6 3.Bb5+ Nc6. White plays c3 and d4 for a big center.',
          '3...d6', '2...d6 3.Bb5+ Nc6로도 나와요. 백은 c3와 d4로 큰 중앙을 세워요.')],
  traps=[])

O('moscow-variation', 'w', 'sicilian', 'e4 c5 Nf3 d6 Bb5+', ['Sicilian Defense: Moscow Variation'],
  en=dict(name='Sicilian Moscow Variation', title='Sicilian Moscow Variation (3.Bb5+): Lines and Stats by Rating',
          desc='The Moscow Variation (1.e4 c5 2.Nf3 d6 3.Bb5+): 3...Bd7, 3...Nd7 and 3...Nc6, plans for both sides and how often each reply is played.',
          lead='3.Bb5+ sidesteps the Najdorf and the Dragon in one move. White develops with check, castles soon and often trades the bishop off, aiming for a calm game with c4, or c3 and d4.',
          white=['After 3...Bd7 4.Bxd7+ Qxd7, castle and play c4 (a Maróczy-style bind) or c3 and d4.',
                 'After 3...Nd7, keep the bishop: O-O, d4 or c3, and Re1 give you a lead in development.',
                 'After 3...Nc6 you are in a Rossolimo with ...d6: O-O and c3 with d4, or Bxc6+ to double the pawns.'],
          black=['3...Bd7 is simple and safe: trade bishops and develop with ...Nc6, ...Nf6 and ...g6 or ...e6.',
                 '3...Nd7 keeps more pieces on and is the choice of many strong players; watch out for an early d4 and e5.',
                 'After 4.Bxd7+, taking back with the queen leaves c6 free for the knight.'],
          club='More than half the players at every rating answer 3.Bb5+ with 3...Bd7, and at 2000+ 3...Nd7 rises to 36%. After 4.Bxd7+ Qxd7, six in ten 2000+ players castle and three in ten play 5.c4.'),
  ko=dict(name='시실리안 모스크바 변화', title='시실리안 모스크바 변화(3.Bb5+): 수순과 레이팅별 응수',
          desc='모스크바 변화(1.e4 c5 2.Nf3 d6 3.Bb5+) 정리: 3...Bd7, 3...Nd7, 3...Nc6, 양쪽 계획과 레이팅별로 많이 두는 응수.',
          lead='3.Bb5+는 한 수로 나이도르프와 드래곤을 피해요. 백은 체크로 전개하고 곧 캐슬링한 뒤 비숍을 바꾸는 일이 많아요. c4, 또는 c3와 d4로 차분한 판을 노려요.',
          white=['3...Bd7 4.Bxd7+ Qxd7 뒤엔 캐슬링하고 c4(마로치식 죄기)나 c3와 d4를 둬요.',
                 '3...Nd7에는 비숍을 남겨요. O-O, d4나 c3, Re1로 전개에서 앞서요.',
                 '3...Nc6면 ...d6가 들어간 로솔리모예요. O-O와 c3·d4, 또는 Bxc6+로 폰을 겹치게 해요.'],
          black=['3...Bd7는 단순하고 안전해요. 비숍을 바꾸고 ...Nc6, ...Nf6, ...g6나 ...e6로 전개해요.',
                 '3...Nd7는 기물을 더 남겨서 강한 사람들이 많이 골라요. 이른 d4와 e5를 조심해요.',
                 '4.Bxd7+에 퀸으로 되잡으면 c6가 나이트 자리로 남아요.'],
          club='모든 레이팅대에서 절반 넘게 3.Bb5+에 3...Bd7로 막고, 2000 이상에서는 3...Nd7가 36%까지 올라가요. 4.Bxd7+ Qxd7 뒤 2000 이상은 열에 여섯이 캐슬링, 열에 셋이 5.c4를 둬요.'),
  vars=[V('e4 c5 Nf3 d6 Bb5+ Bd7 Bxd7+ Qxd7 O-O Nc6 c3 Nf6 d4', '3...Bd7 4.Bxd7+ Qxd7 5.O-O', 'White builds a center with c3 and d4; Black develops and meets it with ...cxd4 and ...e6 or ...g6.',
          '3...Bd7 4.Bxd7+ Qxd7 5.O-O', '백은 c3와 d4로 중앙을 세우고, 흑은 전개하며 ...cxd4와 ...e6나 ...g6로 맞서요.'),
        V('e4 c5 Nf3 d6 Bb5+ Bd7 Bxd7+ Qxd7 c4 Nc6 Nc3', 'Sokolsky, 5.c4', 'Pawns on c4 and e4 hold d5: a calm game where White has more space.',
          '소콜스키, 5.c4', 'c4·e4 폰이 d5를 쥐어요. 백이 공간이 더 넓은 차분한 판이에요.'),
        V('e4 c5 Nf3 d6 Bb5+ Nd7 O-O Nf6 Re1 a6 Bf1', '3...Nd7', 'Black keeps the light-squared bishop. White retreats with Bf1 and plays d4, or c3 and d4.',
          '3...Nd7', '흑이 흰 칸 비숍을 남겨요. 백은 Bf1로 물러나 d4나 c3·d4를 둬요.'),
        V('e4 c5 Nf3 d6 Bb5+ Nc6 O-O Bd7 c3 Nf6 Re1', '3...Nc6', 'The same position as the Rossolimo with 3...d6.',
          '3...Nc6', '로솔리모 3...d6와 같은 국면이에요.')],
  traps=[])

# ---------------------------------------------------------------- other 1.e4
O('french-defense', 'b', 'e4other', 'e4 e6 d4 d5', ['French Defense'],
  en=dict(name='French Defense', title='French Defense: Advance, Exchange, Winawer and Stats by Rating',
          desc='The French Defense (1.e4 e6 2.d4 d5): Advance, Exchange, Tarrasch and Winawer, the plans for both sides, a classic trap and real reply rates.',
          lead='1...e6 and 2...d5 challenge White’s center with a pawn chain. Black gets a solid position but a passive light-squared bishop. The plan is always the same: attack the base of White’s chain with ...c5 and ...f6.',
          white=['3.e5 (Advance) gains space; support e5 with c3, Nf3 and d4.',
                 '3.Nc3 and 3.Nd2 keep tension and lead to the main lines (Winawer, Classical, Tarrasch).',
                 'Attack on the kingside, where your space is; Black’s pieces have little room there.'],
          black=['Hit d4 with ...c5, ...Nc6 and ...Qb6 in the Advance.',
                 'The ...f6 break attacks e5 from the other side.',
                 'Find a job for the c8 bishop: ...b6 and ...Ba6, or ...Bd7–e8–h5.'],
          club='The Advance Variation is the most common at club level because it is simple for White. As Black, ...c5, ...Nc6, ...Qb6 and ...Bd7 cover most games, but beware the classic queen trap below.'),
  ko=dict(name='프렌치 디펜스', title='프렌치 디펜스: 어드밴스·익스체인지·위나워, 레이팅별 응수',
          desc='프렌치 디펜스(1.e4 e6 2.d4 d5) 정리: 어드밴스, 익스체인지, 타라시, 위나워, 양쪽 계획, 고전 함정, 실제 응수 비율.',
          lead='1...e6와 2...d5는 폰 사슬로 백 중앙에 맞서요. 흑은 단단하지만 흰 칸 비숍이 답답해요. 계획은 늘 같아요. ...c5와 ...f6로 백 사슬의 밑을 쳐요.',
          white=['3.e5(어드밴스)로 공간을 얻고, c3, Nf3, d4로 e5를 받쳐요.',
                 '3.Nc3와 3.Nd2는 긴장을 유지하며 주요 갈래(위나워, 클래시컬, 타라시)로 가요.',
                 '공간이 있는 킹 쪽을 공격해요. 흑 말이 그쪽에서 움직일 곳이 적어요.'],
          black=['어드밴스에선 ...c5, ...Nc6, ...Qb6로 d4를 쳐요.',
                 '...f6로 반대쪽에서 e5를 공격해요.',
                 'c8 비숍에 일을 줘요: ...b6와 ...Ba6, 또는 ...Bd7–e8–h5.'],
          club='동호인 대국에선 백에게 단순한 어드밴스 변화가 가장 흔해요. 흑은 ...c5, ...Nc6, ...Qb6, ...Bd7로 대부분 판을 받지만, 아래 고전 퀸 함정은 조심해요.'),
  vars=[V('e4 e6 d4 d5 e5 c5 c3 Nc6 Nf3 Qb6', 'Advance Variation', 'Black piles up on d4. White defends with Be2, O-O and Na3–c2, or plays a3 and b4.',
          '어드밴스 변화', '흑이 d4에 몰려가요. 백은 Be2, O-O, Na3–c2로 지키거나 a3·b4.'),
        V('e4 e6 d4 d5 exd5 exd5', 'Exchange Variation', 'Symmetrical and open. The bishop problem disappears; the game is about piece activity.',
          '익스체인지 변화', '대칭이고 열려 있어요. 비숍 문제가 사라지고, 말을 얼마나 잘 쓰나의 싸움이에요.'),
        V('e4 e6 d4 d5 Nc3 Bb4', 'Winawer Variation', 'Black pins the knight and often gives the bishop for it, doubling White’s pawns. Very sharp.',
          '위나워 변화', '흑이 나이트를 묶고, 그 나이트와 비숍을 바꿔 백 폰을 겹치게 해요. 아주 날카로워요.'),
        V('e4 e6 d4 d5 Nd2', 'Tarrasch Variation', 'The knight on d2 avoids the Winawer pin. Black answers ...c5 or ...Nf6.',
          '타라시 변화', 'd2 나이트로 위나워 핀을 피해요. 흑은 ...c5나 ...Nf6.'),
        V('e4 e6 d4 d5 Nc3 Nf6 Bg5', 'Classical Variation', 'Black develops normally; White pins the knight and pushes e5.',
          '클래시컬 변화', '흑이 평범하게 전개하고, 백은 나이트를 묶은 뒤 e5를 밀어요.')],
  traps=[TR('e4 e6 d4 d5 e5 c5 c3 Nc6 Nf3 Qb6 Bd3 cxd4 cxd4 Nxd4 Nxd4 Qxd4 Bb5+', 'Advance: 8...Qxd4?? 9.Bb5+',
            'In the Advance with 6.Bd3, the d4 pawn looks free. After 7...Nxd4 8.Nxd4 Qxd4?? 9.Bb5+ is a discovered attack: Black blocks the check and White’s queen on d1 takes the queen on d4.',
            '어드밴스: 8...Qxd4?? 9.Bb5+', '6.Bd3 어드밴스에서 d4 폰이 공짜처럼 보여요. 7...Nxd4 8.Nxd4 Qxd4??면 9.Bb5+가 디스커버드 공격이에요. 흑이 체크를 막는 사이 d1의 백 퀸이 d4의 퀸을 잡아요.')])

O('caro-kann-defense', 'b', 'e4other', 'e4 c6 d4 d5', ['Caro-Kann Defense'],
  en=dict(name='Caro-Kann Defense', title='Caro-Kann Defense: Advance, Exchange, Classical, Stats by Rating',
          desc='The Caro-Kann (1.e4 c6 2.d4 d5): Advance, Exchange, Classical and Two Knights lines, plans for both sides, a famous smothered mate and real reply rates.',
          lead='1...c6 prepares ...d5 with pawn support. Unlike the French, Black’s light-squared bishop gets out before ...e6, so the position is solid without being cramped.',
          white=['3.e5 (Advance) is the most popular; meet ...Bf5 with Nf3, Be2 and O-O, or the sharp g4.',
                 '3.Nc3 or 3.Nd2 dxe4 4.Nxe4 leads to the Classical: White gets space, Black a rock-solid position.',
                 'The Exchange (3.exd5 cxd5) and the Panov (4.c4) give open, active games.'],
          black=['Get the bishop out with ...Bf5 or ...Bg4 before playing ...e6.',
                 'In the Advance, ...c5 is the key break; in the Classical, ...c5 or ...e5 frees the game.',
                 'In the 4...Nd7 lines, check for Nd6 tricks before you move the g8 knight (see the trap below).'],
          club='The Caro-Kann has a reputation for being boring, but below 2000 Black scores a little better with it than with the average answer to 1.e4. The one trap every Caro-Kann player must know is the smothered mate below.'),
  ko=dict(name='카로칸 디펜스', title='카로칸 디펜스: 어드밴스·익스체인지·클래시컬, 레이팅별 응수',
          desc='카로칸(1.e4 c6 2.d4 d5) 정리: 어드밴스, 익스체인지, 클래시컬, 투 나이츠 갈래, 양쪽 계획, 유명한 스머더드 메이트, 실제 응수 비율.',
          lead='1...c6는 폰으로 받친 ...d5를 준비해요. 프렌치와 달리 흑의 흰 칸 비숍이 ...e6 전에 밖으로 나와서, 단단하면서도 답답하지 않아요.',
          white=['3.e5(어드밴스)가 가장 인기 있어요. ...Bf5에는 Nf3, Be2, O-O나 날카로운 g4.',
                 '3.Nc3나 3.Nd2 dxe4 4.Nxe4는 클래시컬이에요. 백은 공간을, 흑은 바위 같은 판을 얻어요.',
                 '익스체인지(3.exd5 cxd5)와 파노프(4.c4)는 열리고 활발한 판을 줘요.'],
          black=['...e6 전에 ...Bf5나 ...Bg4로 비숍을 꺼내요.',
                 '어드밴스에선 ...c5가 핵심, 클래시컬에선 ...c5나 ...e5가 숨통을 틔워요.',
                 '4...Nd7 갈래에서는 g8 나이트를 움직이기 전에 Nd6 수를 확인해요(아래 함정).'],
          club='카로칸은 지루하다는 말을 듣지만 2000 아래에서는 1.e4에 대한 평균 응수보다 흑 성적이 조금 좋아요. 카로칸을 두는 사람은 아래 스머더드 메이트 하나만은 꼭 알아야 해요.'),
  vars=[V('e4 c6 d4 d5 e5 Bf5 Nf3 e6 Be2', 'Advance, Short Variation', 'Calm and modern. White castles and plays c3 or c4; Black plays ...c5 and ...Nd7.',
          '어드밴스, 쇼트 변화', '차분한 요즘 갈래예요. 백은 캐슬링 뒤 c3나 c4, 흑은 ...c5와 ...Nd7.'),
        V('e4 c6 d4 d5 Nc3 dxe4 Nxe4 Bf5 Ng3 Bg6', 'Classical Variation', 'The bishop comes out with tempo. White plays h4–h5 to gain space.',
          '클래시컬 변화', '비숍이 시간을 벌며 나와요. 백은 h4–h5로 공간을 얻어요.'),
        V('e4 c6 d4 d5 exd5 cxd5 Bd3 Nc6 c3', 'Exchange Variation', 'A Queen’s Gambit Declined Exchange with colors reversed. Simple and solid.',
          '익스체인지 변화', '색을 바꾼 퀸스 갬빗 거절 익스체인지예요. 단순하고 단단해요.'),
        V('e4 c6 Nc3 d5 Nf3', 'Two Knights Attack', 'White keeps d2–d4 back and develops knights first. 3...Bg4 or 3...dxe4 are good.',
          '투 나이츠 공격', '백이 d4를 미루고 나이트부터 꺼내요. 3...Bg4나 3...dxe4가 좋아요.'),
        V('e4 c6 d4 d5 f3 dxe4 fxe4 e5 Nf3 exd4 Bc4', 'Fantasy (Maróczy) Variation, 3.f3', 'White backs up e4 with a pawn. After 3...dxe4 4.fxe4 e5 5.Nf3 exd4 6.Bc4 White scores about 61% for the pawn; 3...e6 is the calmer answer.',
          '판타지(마로치) 변화, 3.f3', '백이 폰으로 e4를 받쳐요. 3...dxe4 4.fxe4 e5 5.Nf3 exd4 6.Bc4 뒤 백 점수는 61% 정도라서 폰 하나 값을 충분히 해요. 더 차분한 응수는 3...e6예요.')],
  traps=[TR('e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Qe2 Ngf6 Nd6#', 'The Qe2 smothered mate',
            'In the 4...Nd7 Classical, 5.Qe2 looks harmless. But 5...Ngf6?? 6.Nd6 is mate: the e7 pawn is pinned by the queen, so it cannot take the knight, and the king has no square. Black plays 5...Ndf6 instead.',
            'Qe2 스머더드 메이트', '4...Nd7 클래시컬에서 5.Qe2는 별것 없어 보여요. 그런데 5...Ngf6??면 6.Nd6로 메이트예요. e7 폰이 퀸에 묶여 나이트를 못 잡고 킹도 갈 곳이 없어요. 흑은 5...Ndf6를 둬요.', end='mate')])

O('scandinavian-defense', 'b', 'e4other', 'e4 d5', ['Scandinavian Defense'],
  en=dict(name='Scandinavian Defense', title='Scandinavian Defense: Qa5, Qd6, Qd8 and 2...Nf6 by Rating',
          desc='The Scandinavian Defense (1.e4 d5): the 3...Qa5, 3...Qd6 and 3...Qd8 lines, the Modern 2...Nf6, plans for both sides and real reply rates.',
          lead='1...d5 challenges e4 at once. After 2.exd5 Qxd5 Black’s queen comes out early, but it is easy to find a safe square. You get the same kind of position against almost every White setup, which makes it a great low-theory weapon.',
          white=['3.Nc3 gains a tempo on the queen; then d4, Nf3 and Bc4 or Bd2.',
                 'Your pawn on d4 gives you more space; Ne5 and a quick c4 are typical ways to use it.',
                 'Against 2...Nf6, 3.d4 Nxd5 4.Nf3 is simple; holding the pawn with 3.c4 invites the ...c6 or ...e6 gambits.'],
          black=['Choose your queen square: a5 (active), d6 (modern) or d8 (solid).',
                 'Develop with ...Nf6, ...c6, ...Bf5 or ...Bg4 and ...e6; this setup works against almost everything.',
                 'Do not let White’s pieces gain more tempi on the queen.'],
          club='The Scandinavian is common below 1600 because it avoids theory. From 1200 up most White players answer 2.exd5 and 3.Nc3, so learning one queen retreat and one setup covers most of your games; under 1200, expect 2.e5 too.'),
  ko=dict(name='스칸디나비안 디펜스', title='스칸디나비안 디펜스: Qa5·Qd6·Qd8와 2...Nf6, 레이팅별 응수',
          desc='스칸디나비안 디펜스(1.e4 d5) 정리: 3...Qa5, 3...Qd6, 3...Qd8 갈래, 모던 2...Nf6, 양쪽 계획, 실제 응수 비율.',
          lead='1...d5는 바로 e4에 맞서요. 2.exd5 Qxd5 뒤 흑 퀸이 일찍 나오지만 안전한 칸을 찾기 쉬워요. 백이 뭘 두든 거의 같은 모양이 나와서 이론이 적은 좋은 무기예요.',
          white=['3.Nc3로 퀸을 치며 시간을 벌고, d4, Nf3, Bc4나 Bd2.',
                 'd4 폰이 공간을 줘요. Ne5나 빠른 c4로 그 공간을 써요.',
                 '2...Nf6에는 3.d4 Nxd5 4.Nf3가 단순해요. 3.c4로 폰을 지키면 ...c6나 ...e6 갬빗을 만나요.'],
          black=['퀸 자리를 골라요: a5(활발), d6(요즘), d8(단단).',
                 '...Nf6, ...c6, ...Bf5나 ...Bg4, ...e6로 전개해요. 이 배치는 거의 모든 수에 통해요.',
                 '백 말이 퀸을 치며 시간을 더 벌게 두지 말아요.'],
          club='스칸디나비안은 이론을 피할 수 있어서 1600 아래에서 흔해요. 1200 이상에서는 백 대부분이 2.exd5와 3.Nc3를 두니, 퀸 자리 하나와 배치 하나만 익혀도 판 대부분을 받아요. 1200 미만에서는 2.e5도 자주 나와요.'),
  vars=[V('e4 d5 exd5 Qxd5 Nc3 Qa5 d4 Nf6 Nf3 c6', 'Main line, 3...Qa5', 'The classical main line. Black plays ...Bf5 or ...Bg4 and ...e6.',
          '주요 수순, 3...Qa5', '고전 주요 수순이에요. 흑은 ...Bf5나 ...Bg4와 ...e6.'),
        V('e4 d5 exd5 Qxd5 Nc3 Qd6', 'Modern, 3...Qd6', 'The queen is safe on d6 and supports ...a6 and ...Nf6. Popular since the 2010s.',
          '모던, 3...Qd6', '퀸이 d6에서 안전하고 ...a6, ...Nf6를 받쳐요. 2010년대부터 인기예요.'),
        V('e4 d5 exd5 Qxd5 Nc3 Qd8', 'Retreat to d8', 'Solid but slow; Black gives White a free center.',
          'd8로 물러나기', '단단하지만 느려요. 백에게 중앙을 거저 줘요.'),
        V('e4 d5 exd5 Nf6', 'Modern Variation, 2...Nf6', 'Black takes back with the knight later. White can keep the pawn with c4 or play d4.',
          '모던 변화, 2...Nf6', '흑이 나중에 나이트로 되잡아요. 백은 c4로 폰을 지키거나 d4.')],
  traps=[])

O('pirc-defense', 'b', 'e4other', 'e4 d6 d4 Nf6 Nc3 g6', ['Pirc Defense', 'Lion Defense', 'Czech Defense', 'Rat Defense'],
  en=dict(name='Pirc Defense', title='Pirc Defense: Austrian, 150 Attack, Lion and Czech by Rating',
          desc='The Pirc Defense (1.e4 d6 2.d4 Nf6 3.Nc3 g6): the Austrian Attack, the 150 Attack, the Classical, and the Lion and Czech setups, with reply rates by rating.',
          lead='Black lets White build a big center and plans to attack it later with ...c5 or ...e5. The bishop on g7 is the key piece. It is flexible and avoids theory, but White gets free attacking chances.',
          white=['The Austrian Attack (f4) grabs maximum space; the 150 Attack (Be3, Qd2, Bh6) aims at the king.',
                 'The Classical (Nf3, Be2, O-O) is calm and keeps a small edge.',
                 'Trade Black’s g7 bishop with Bh6 when you castle long.'],
          black=['Strike the center with ...e5 or ...c5 once you have castled.',
                 'Against Be3 and Qd2, do not castle into an attack without ...c6 and ...b5 counterplay.',
                 'The Modern Defense (...g6 without ...Nf6) keeps even more options open and has its own guide.'],
          club='Below 2000 the most common answer to 3...g6 is the calm 4.Nf3, with 4.Bg5 second. At 2000+ the choices are spread between 4.f4 (20%), 4.Nf3, 4.Be3 and 4.Bg5. White scores about 54% after 4.Be3, so learn when to delay castling against the Be3–Qd2–Bh6 plan.'),
  ko=dict(name='피르츠 디펜스', title='피르츠 디펜스: 오스트리안·150 어택·라이언·체코, 레이팅별 응수',
          desc='피르츠 디펜스(1.e4 d6 2.d4 Nf6 3.Nc3 g6) 정리: 오스트리안 어택, 150 어택, 클래시컬, 라이언·체코 배치, 레이팅별 응수 비율.',
          lead='흑이 백에게 큰 중앙을 허락하고 나중에 ...c5나 ...e5로 치는 계획이에요. g7 비숍이 핵심이에요. 유연하고 이론이 적지만, 백도 공격 기회를 거저 얻어요.',
          white=['오스트리안 어택(f4)은 공간을 최대로, 150 어택(Be3, Qd2, Bh6)은 킹을 노려요.',
                 '클래시컬(Nf3, Be2, O-O)은 차분하게 작은 우위를 지켜요.',
                 '긴 캐슬링을 하면 Bh6로 흑 g7 비숍을 바꿔요.'],
          black=['캐슬링 뒤 ...e5나 ...c5로 중앙을 쳐요.',
                 'Be3·Qd2 배치에는 ...c6, ...b5 반격 없이 공격받는 쪽으로 캐슬링하지 않아요.',
                 '모던 디펜스(...Nf6 없이 ...g6)는 선택지를 더 많이 남겨요. 따로 해설이 있어요.'],
          club='2000 아래에서는 3...g6에 차분한 4.Nf3가 가장 많고 4.Bg5가 그다음이에요. 2000 이상에서는 4.f4(20%), 4.Nf3, 4.Be3, 4.Bg5로 고르게 나뉘어요. 4.Be3 뒤 백 점수는 54% 정도이니, Be3–Qd2–Bh6 계획에 맞서 캐슬링을 언제 미룰지부터 익히세요.'),
  vars=[V('e4 d6 d4 Nf6 Nc3 g6 f4 Bg7 Nf3', 'Austrian Attack', 'White builds e4, d4 and f4. Black answers ...O-O and ...c5 or ...Na6.',
          '오스트리안 어택', '백이 e4, d4, f4를 쌓아요. 흑은 ...O-O 뒤 ...c5나 ...Na6.'),
        V('e4 d6 d4 Nf6 Nc3 g6 Be3 c6 Qd2', '150 Attack', 'White plans Bh6, O-O-O and h4. Black plays ...b5 and delays castling.',
          '150 어택', '백은 Bh6, O-O-O, h4를 노리고, 흑은 ...b5를 두며 캐슬링을 미뤄요.'),
        V('e4 d6 d4 Nf6 Nc3 g6 Nf3 Bg7 Be2 O-O O-O', 'Classical Variation', 'Calm. Black plays ...c6, ...Bg4 or ...e5.',
          '클래시컬 변화', '차분해요. 흑은 ...c6, ...Bg4, ...e5.'),
        V('e4 d6 d4 Nf6 Nc3 Nbd7 f4 e5 Nf3', 'Lion Defense, 3...Nbd7', 'Black keeps the g7 bishop at home and plays ...e5 with a Philidor-like structure (the “Lion’s Jaw”). Solid but cramped.',
          '라이언 디펜스, 3...Nbd7', '흑은 g7 비숍 대신 ...e5로 필리도르 같은 구조를 만들어요. 단단하지만 답답해요.'),
        V('e4 d6 d4 Nf6 Nc3 c6 f4 Qa5', 'Czech Defense, 3...c6', 'Black prepares ...e5 or ...b5 and keeps the queen active on a5. Less theory than the Pirc.',
          '체코 디펜스, 3...c6', '흑이 ...e5나 ...b5를 준비하고 퀸을 a5에 활발하게 둬요. 피르츠보다 이론이 적어요.')],
  traps=[])

O('alekhine-defense', 'b', 'e4other', 'e4 Nf6', ['Alekhine Defense'],
  en=dict(name='Alekhine Defense', title='Alekhine Defense: Four Pawns, Modern, Exchange, Stats by Rating',
          desc='The Alekhine Defense (1.e4 Nf6): the Four Pawns Attack, Modern and Exchange variations, plans for both sides and real reply rates by rating.',
          lead='1...Nf6 invites White’s pawns forward: after 2.e5 Nd5 White can chase the knight with c4 and d4 and build a huge center. Black’s idea is that a big center is also a big target.',
          white=['2.e5 Nd5 3.d4 d6 4.Nf3 (Modern) is the most solid choice.',
                 'The Four Pawns Attack (c4, d4, e5, f4) is ambitious but over-extended if you are careless.',
                 '2.Nc3 avoids all of this and often transposes to a Vienna or Scandinavian.'],
          black=['After White’s pawns advance, hit them with ...d6, ...c5 or ...f6.',
                 'Aim your pieces at the pawns: ...Nc6, ...Bf5 or ...Bg4 and ...dxe5 turn the big center into a target.',
                 'Do not leave the knight on d5 to be chased forever; ...Nb6 is its usual home.'],
          club='The Alekhine is rare, so many club opponents do not know what to do. From 1200 up, 2.e5 is the most common answer (under 1200 it is 2.Nc3), and the main line goes 2...Nd5 3.d4 d6 with 4.c4 or 4.Nf3.'),
  ko=dict(name='알레힌 디펜스', title='알레힌 디펜스: 포 폰스·모던·익스체인지, 레이팅별 응수',
          desc='알레힌 디펜스(1.e4 Nf6) 정리: 포 폰스 어택, 모던·익스체인지 변화, 양쪽 계획, 레이팅별 실제 응수 비율.',
          lead='1...Nf6는 백 폰을 앞으로 불러내요. 2.e5 Nd5 뒤 백은 c4와 d4로 나이트를 쫓으며 큰 중앙을 쌓을 수 있어요. 흑의 생각은 큰 중앙이 큰 표적이기도 하다는 거예요.',
          white=['2.e5 Nd5 3.d4 d6 4.Nf3(모던)가 가장 단단한 선택이에요.',
                 '포 폰스 어택(c4, d4, e5, f4)은 야심 차지만 조심하지 않으면 너무 나가요.',
                 '2.Nc3는 이 모든 걸 피하고 비엔나나 스칸디나비안으로 자주 넘어가요.'],
          black=['백 폰이 나오면 ...d6, ...c5, ...f6로 쳐요.',
                 '말로 폰을 노려요. ...Nc6, ...Bf5나 ...Bg4, ...dxe5로 큰 중앙을 과녁으로 만들어요.',
                 'd5 나이트가 계속 쫓기게 두지 말아요. 보통 자리는 ...Nb6.'],
          club='알레힌은 드물어서 동호인 상대 상당수가 어떻게 할지 몰라요. 1200 이상에서는 2.e5가 가장 흔하고(1200 미만은 2.Nc3), 주요 수순은 2...Nd5 3.d4 d6 뒤 4.c4나 4.Nf3예요.'),
  vars=[V('e4 Nf6 e5 Nd5 d4 d6 Nf3 Bg4 Be2 e6', 'Modern Variation', 'The main line. Black pins the knight and plays ...e6, ...Be7 and ...O-O.',
          '모던 변화', '주요 수순이에요. 흑은 나이트를 묶고 ...e6, ...Be7, ...O-O.'),
        V('e4 Nf6 e5 Nd5 d4 d6 c4 Nb6 f4', 'Four Pawns Attack', 'White’s maximal center. Black hits back with ...dxe5, ...Bf5 and ...Nc6.',
          '포 폰스 어택', '백의 최대 중앙이에요. 흑은 ...dxe5, ...Bf5, ...Nc6로 되쳐요.'),
        V('e4 Nf6 e5 Nd5 d4 d6 c4 Nb6 exd6', 'Exchange Variation', 'White trades on d6 for a space edge. Black chooses ...cxd6 or ...exd6.',
          '익스체인지 변화', '백이 d6에서 바꿔 공간 우위를 얻어요. 흑은 ...cxd6나 ...exd6.'),
        V('e4 Nf6 Nc3 d5', 'Scandinavian Variation', 'White avoids the main lines. Black hits e4 at once.',
          '스칸디나비안 변화', '백이 주요 수순을 피해요. 흑은 바로 e4를 쳐요.')],
  traps=[])

O('modern-defense', 'b', 'e4other', 'e4 g6 d4 Bg7',
  ['Modern Defense', "Queen's Pawn Game: Modern Defense", 'Pterodactyl Defense', 'Robatsch Defense', 'Hippopotamus Defense',
   'Rat Defense: Accelerated Gurgenidze'],
  en=dict(name='Modern Defense', title='Modern Defense (1...g6): Lines, Plans and Stats by Rating',
          desc='The Modern Defense (1.e4 g6): 3.Nc3 with Be3 and Qd2, the Three Pawns Attack, the Pterodactyl and the Hippopotamus setup, and how often each is played.',
          lead='1...g6 lets White build any center and then attacks it from the side. The g7 bishop hits d4 and the pawns stay flexible, so the same setup works against almost anything. The risk is that White simply takes too much space.',
          white=['3.Nc3 d6 4.Be3 with Qd2, f3 and O-O-O is the most popular plan at 2000+: trade the g7 bishop with Bh6 and attack.',
                 '3.Nf3 with Be2 or Bc4 and O-O is a quiet, solid setup.',
                 '3.f4 (Three Pawns Attack) grabs the most space but needs care: Black hits the center with ...c5 or ...d5.'],
          black=['Usual setup: ...d6 with ...a6 and ...b5, or ...Nd7 and ...c5. Adding ...Nf6 turns it into a Pirc.',
                 'Strike the center with ...c5 or ...e5 once your pieces are out; do not just wait.',
                 'The Hippopotamus (...g6, ...b6, ...Bb7, ...Bg7, ...d6, ...e6, ...Nd7, ...Ne7) is a slow wall that works best against players who overpress.'],
          club='Below 1600 the most common answer to 2...Bg7 is 3.Nf3, and below 1200 three in ten push 3.e5. At 2000+ 3.Nc3 leads (36%), and after 3...d6 the top choice is 4.Be3 (42%). White scores about 54% after 3.Nc3 d6.'),
  ko=dict(name='모던 디펜스', title='모던 디펜스(1...g6): 수순·계획·레이팅별 응수',
          desc='모던 디펜스(1.e4 g6) 정리: 3.Nc3와 Be3·Qd2, 스리 폰즈 어택, 프테로닥틸, 하마(히포) 배치, 레이팅별로 많이 두는 수.',
          lead='1...g6는 백이 중앙을 마음대로 세우게 두고 옆에서 쳐요. g7 비숍이 d4를 노리고 폰은 유연하게 남아서, 같은 배치로 거의 모든 수에 맞설 수 있어요. 위험은 백이 공간을 너무 많이 가져가는 거예요.',
          white=['3.Nc3 d6 4.Be3 뒤 Qd2, f3, O-O-O가 2000 이상에서 가장 인기 있는 계획이에요. Bh6로 g7 비숍을 바꾸고 공격해요.',
                 '3.Nf3와 Be2나 Bc4, O-O는 조용하고 단단한 배치예요.',
                 '3.f4(스리 폰즈 어택)는 공간을 가장 많이 잡지만 조심해야 해요. 흑이 ...c5나 ...d5로 중앙을 쳐요.'],
          black=['흔한 배치: ...d6와 ...a6·...b5, 또는 ...Nd7와 ...c5. 여기에 ...Nf6를 더하면 피르츠가 돼요.',
                 '말이 나오면 ...c5나 ...e5로 중앙을 쳐요. 그냥 기다리기만 하면 안 돼요.',
                 '하마(히포) 배치(...g6, ...b6, ...Bb7, ...Bg7, ...d6, ...e6, ...Nd7, ...Ne7)는 느린 벽이에요. 무리하게 밀어붙이는 상대에게 가장 잘 통해요.'],
          club='1600 아래에서는 2...Bg7에 3.Nf3가 가장 많고, 1200 미만에서는 열에 셋이 3.e5를 밀어요. 2000 이상에서는 3.Nc3가 앞서고(36%), 3...d6 뒤엔 4.Be3가 가장 많아요(42%). 3.Nc3 d6 뒤 백 점수는 54% 정도예요.'),
  vars=[V('e4 g6 d4 Bg7 Nc3 d6 Be3 a6 Qd2 b5', 'Standard line, 4.Be3 a6', 'Black grabs queenside space with ...b5 and ...Bb7 while White prepares O-O-O and Bh6.',
          '기본 수순, 4.Be3 a6', '흑은 ...b5와 ...Bb7로 퀸 쪽 공간을 잡고, 백은 O-O-O와 Bh6를 준비해요.'),
        V('e4 g6 d4 Bg7 Nc3 c6 f4 d5 e5', 'Gurgenidze, 3...c6 and ...d5', 'Black builds a Caro-Kann-like wall with ...c6 and ...d5; White locks the center with e5.',
          '구르게니제, 3...c6와 ...d5', '흑이 ...c6와 ...d5로 카로칸 같은 벽을 쌓고, 백은 e5로 중앙을 잠가요.'),
        V('e4 g6 d4 Bg7 f4 d6 Nf3', 'Three Pawns Attack, 3.f4', 'White takes the whole center. Black hits it with ...c5, or with ...Nf6 and ...O-O first.',
          '스리 폰즈 어택, 3.f4', '백이 중앙을 다 차지해요. 흑은 ...c5로, 또는 ...Nf6와 ...O-O 뒤에 쳐요.'),
        V('e4 g6 d4 Bg7 Nc3 c5', 'Pterodactyl, 3...c5', 'Black hits d4 at once and often brings the queen to a5.',
          '프테로닥틸, 3...c5', '흑이 바로 d4를 치고, 퀸을 a5로 자주 보내요.'),
        V('e4 g6 d4 Bg7 Nf3 d6 Be2 b6 O-O Bb7 c4 e6 Nc3 Nd7', 'Hippopotamus setup', 'Black puts every piece behind the pawns on b6, d6, e6 and g6 and waits for White to overextend.',
          '하마(히포) 배치', '흑이 b6, d6, e6, g6 폰 뒤에 모든 말을 두고 백이 무리하기를 기다려요.'),
        V('e4 g6 d4 Bg7 Bc4 d6 Qf3 e6', 'Bishop Attack, 3.Bc4 and Qf3', 'White lines up on f7. ...e6 closes the diagonal, and the queen on f3 later becomes a target.',
          '비숍 어택, 3.Bc4와 Qf3', '백이 f7을 겨눠요. ...e6로 대각선을 막으면 f3 퀸은 나중에 표적이 돼요.'),
        V('d4 g6 c4 Bg7 Nc3 d6 e4', 'Against 1.d4: 1...g6', 'The same setup works against 1.d4. After c4 and Nc3, ...Nf6 leads to a King’s Indian and ...c5 to a Benoni.',
          '1.d4에 1...g6', '1.d4에도 같은 배치를 써요. c4와 Nc3 뒤 ...Nf6면 킹스 인디언, ...c5면 베노니가 돼요.')],
  traps=[])

O('nimzowitsch-defense', 'b', 'e4other', 'e4 Nc6', ['Nimzowitsch Defense'],
  en=dict(name='Nimzowitsch Defense', title='Nimzowitsch Defense (1...Nc6): Lines and Stats by Rating',
          desc='The Nimzowitsch Defense (1.e4 Nc6): 2.d4 d5, the Kennedy 2...e5, the Williams 2.Nf3 d6 and transpositions, with how often each is played at your rating.',
          lead='1...Nc6 develops a knight and dares White to take the center. Black can answer with ...d5 (hitting e4), ...e5 (hitting d4) or a slow ...d6 and ...Nf6, and many games turn into ordinary 1...e5 openings after 2.Nf3 e5.',
          white=['2.d4 grabs the center. After 2...d5 choose 3.e5 for space or 3.Nc3 to keep the tension.',
                 '2.Nf3 is simplest: after 2...e5 you are in a normal open game, and after 2...d6 play 3.d4 Nf6 4.Nc3.',
                 'Against 2.d4 e5, 3.d5 Nce7 gains space and kicks the knight back.'],
          black=['After 2.d4 d5 3.e5, play 3...Bf5 to develop the bishop before ...e6, as in the Caro-Kann Advance.',
                 '2...e5 is the Kennedy: after 3.d5 the knight goes to e7, after 3.dxe5 take back with 3...Nxe5.',
                 'If you just want a normal game, answer 2.Nf3 with 2...e5.'],
          club='Below 1200 White scores about 54% after 1...Nc6, but at 2000+ only about 50%, so it holds up well at higher ratings. At 2000+ almost half answer 2.d4, and after 2.d4 d5 3.e5 three in four strong players reply 3...Bf5.'),
  ko=dict(name='님조비치 디펜스', title='님조비치 디펜스(1...Nc6): 수순과 레이팅별 응수',
          desc='님조비치 디펜스(1.e4 Nc6) 정리: 2.d4 d5, 케네디 2...e5, 윌리엄스 2.Nf3 d6와 다른 오프닝으로 옮겨 가는 길, 레이팅별로 많이 두는 수.',
          lead='1...Nc6는 나이트를 전개하면서 백에게 중앙을 가져가 보라고 해요. 흑은 ...d5(e4 공격), ...e5(d4 공격), 또는 느린 ...d6와 ...Nf6로 받을 수 있고, 2.Nf3 e5 뒤엔 평범한 1...e5 오프닝이 되는 판도 많아요.',
          white=['2.d4로 중앙을 잡아요. 2...d5에는 공간을 원하면 3.e5, 긴장을 유지하려면 3.Nc3.',
                 '2.Nf3가 가장 단순해요. 2...e5면 평범한 오픈 게임, 2...d6면 3.d4 Nf6 4.Nc3.',
                 '2.d4 e5에는 3.d5 Nce7로 공간을 얻고 나이트를 물려요.'],
          black=['2.d4 d5 3.e5 뒤엔 카로칸 어드밴스처럼 ...e6 전에 3...Bf5로 비숍을 꺼내요.',
                 '2...e5가 케네디 변화예요. 3.d5에는 나이트가 e7로, 3.dxe5에는 3...Nxe5로 되잡아요.',
                 '평범한 판을 원하면 2.Nf3에 2...e5로 받아요.'],
          club='1200 미만에서는 1...Nc6 뒤 백 점수가 54% 정도지만 2000 이상에서는 50% 정도라서, 레이팅이 높아져도 잘 버텨요. 2000 이상에서는 절반 가까이가 2.d4를 두고, 2.d4 d5 3.e5 뒤엔 넷에 셋이 3...Bf5로 받아요.'),
  vars=[V('e4 Nc6 d4 d5 e5 Bf5 Nf3 e6', 'Scandinavian Variation, 2.d4 d5 3.e5', 'Like a Caro-Kann Advance with the knight on c6: Black plays ...Bf5, ...e6 and later ...f6 to hit the chain.',
          '스칸디나비안 변화, 2.d4 d5 3.e5', '나이트가 c6에 있는 카로칸 어드밴스 같아요. 흑은 ...Bf5, ...e6, 나중에 ...f6로 폰 사슬을 쳐요.'),
        V('e4 Nc6 d4 d5 Nc3 dxe4 d5 Ne5', '2.d4 d5 3.Nc3', 'White keeps the tension; after 3...dxe4 4.d5 the knight goes to e5 and both sides play fast.',
          '2.d4 d5 3.Nc3', '백이 긴장을 유지해요. 3...dxe4 4.d5 뒤 나이트는 e5로 가고 양쪽 다 빠르게 둬요.'),
        V('e4 Nc6 d4 e5 d5 Nce7', 'Kennedy Variation, 2...e5 3.d5', 'White gains space with tempo. Black reroutes with ...Ng6 and plays ...Bc5 or ...d6.',
          '케네디 변화, 2...e5 3.d5', '백이 템포를 얻으며 공간을 잡아요. 흑은 ...Ng6로 옮기고 ...Bc5나 ...d6를 둬요.'),
        V('e4 Nc6 Nf3 d6 d4 Nf6 Nc3 Bg4', 'Williams Variation, 2.Nf3 d6', 'Black plays ...Nf6 and ...Bg4 in a Pirc-like position; White keeps a pleasant center.',
          '윌리엄스 변화, 2.Nf3 d6', '흑이 ...Nf6와 ...Bg4로 피르츠 비슷한 판을 만들고, 백은 편한 중앙을 유지해요.'),
        V('e4 Nc6 Nf3 e5', '2.Nf3 e5', 'A normal open game: 3.Bb5, 3.Bc4 or 3.d4 lead to the Ruy Lopez, Italian or Scotch.',
          '2.Nf3 e5', '평범한 오픈 게임이에요. 3.Bb5, 3.Bc4, 3.d4로 루이 로페즈, 이탈리안, 스카치가 돼요.')],
  traps=[])

O('owen-defense', 'b', 'e4other', 'e4 b6', ['Owen Defense'],
  en=dict(name='Owen Defense', title='Owen Defense (1...b6): Lines, Plans and Stats by Rating',
          desc='The Owen Defense (1.e4 b6): the b7 bishop against e4, 2.d4 Bb7 3.Bd3 and 3.Nc3, a mating trap after 3...f5, and how often each reply is played.',
          lead='1...b6 prepares ...Bb7 to hit e4 from far away. It is easy to learn and avoids theory, but it hands White the center, and if Black is slow to challenge it White gets an easy space advantage.',
          white=['2.d4 Bb7 3.Bd3 is the most common setup at 2000+: the bishop protects e4 and points at the kingside.',
                 '3.Nc3 also protects e4; follow up with Nf3, O-O and Re1.',
                 'Do not hurry with e5 or d5; a solid center backed by c3 or c4 is enough.'],
          black=['After 3.Bd3 play 3...e6 with ...c5 or ...Nf6: hit the center before White finishes developing.',
                 'The b7 bishop is your best piece, so keep the long diagonal open.',
                 'If White plays 3.d5, attack the pawn at once with ...e6 or ...Nf6.'],
          club='Below 1200 three in ten answer 2...Bb7 with 3.d5, which blocks the bishop but leaves the pawn loose. At 2000+ half play 3.Bd3. White scores about 55% after 3.Bd3, so the Owen is a surprise weapon rather than a main repertoire.'),
  ko=dict(name='오웬 디펜스', title='오웬 디펜스(1...b6): 수순·계획·레이팅별 응수',
          desc='오웬 디펜스(1.e4 b6) 정리: b7 비숍과 e4, 2.d4 Bb7 3.Bd3와 3.Nc3, 3...f5 뒤의 메이트 함정, 레이팅별로 많이 두는 응수.',
          lead='1...b6는 ...Bb7를 준비해 멀리서 e4를 쳐요. 배우기 쉽고 이론을 피하지만 백에게 중앙을 내주고, 흑이 늦게 맞서면 백이 쉽게 공간 우세를 얻어요.',
          white=['2.d4 Bb7 3.Bd3가 2000 이상에서 가장 많은 배치예요. 비숍이 e4를 지키고 킹 쪽을 겨눠요.',
                 '3.Nc3도 e4를 지켜요. 이어서 Nf3, O-O, Re1.',
                 'e5나 d5를 서두르지 않아요. c3나 c4로 받친 단단한 중앙이면 충분해요.'],
          black=['3.Bd3에는 3...e6 뒤 ...c5나 ...Nf6로, 백 전개가 끝나기 전에 중앙을 쳐요.',
                 'b7 비숍이 흑의 가장 좋은 말이에요. 긴 대각선을 열어 둬요.',
                 '백이 3.d5를 두면 ...e6나 ...Nf6로 바로 그 폰을 쳐요.'],
          club='1200 미만에서는 열에 셋이 2...Bb7에 3.d5를 밀어요. 비숍은 막지만 폰이 약해져요. 2000 이상에서는 절반이 3.Bd3를 둬요. 3.Bd3 뒤 백 점수는 55% 정도라서, 오웬은 주력보다는 기습용이에요.'),
  vars=[V('e4 b6 d4 Bb7 Bd3 e6 Nf3 c5 c3', '3.Bd3 e6', 'The main line: Black plays ...c5 and ...Nf6, and White holds the center with c3.',
          '3.Bd3 e6', '주요 수순이에요. 흑은 ...c5와 ...Nf6, 백은 c3로 중앙을 지켜요.'),
        V('e4 b6 d4 Bb7 Nc3 e6 Nf3 Bb4 Bd3', '3.Nc3 e6', 'Black pins the knight with ...Bb4 to keep up the pressure on e4.',
          '3.Nc3 e6', '흑이 ...Bb4로 나이트를 핀해서 e4 압박을 이어 가요.'),
        V('e4 b6 d4 Bb7 d5 e6 c4', '3.d5', 'White blocks the bishop, but the d5 pawn needs support; ...e6 and ...Nf6 go after it.',
          '3.d5', '백이 비숍을 막지만 d5 폰을 받쳐야 해요. ...e6와 ...Nf6로 그 폰을 노려요.'),
        V('e4 b6 d4 Bb7 Bd3 g6', 'Double fianchetto, 3...g6', 'Both bishops go to the long diagonals and fight e4 and d4 from the sides.',
          '쌍 피앙케토, 3...g6', '두 비숍을 긴 대각선에 놓고 옆에서 e4와 d4를 다퉈요.')],
  traps=[TR('e4 b6 d4 Bb7 Bd3 f5 exf5 Bxg2 Qh5+ g6 fxg6 Nf6 gxh7+ Nxh5 Bg6#', '3...f5?! 4.exf5 Bxg2? 5.Qh5+',
            'Grabbing the g2 pawn spends the move Black needed for ...Nf6, so 5.Qh5+ comes down the open e8–h5 diagonal. After 5.Qh5+ g6 6.fxg6 the natural 6...Nf6?? loses at once: 7.gxh7+ is a discovered check, and after 7...Nxh5 8.Bg6 is mate.',
            '3...f5?! 4.exf5 Bxg2? 5.Qh5+', 'g2 폰을 먹느라 ...Nf6를 둘 시간을 써서, 5.Qh5+가 열린 e8–h5 대각선으로 들어와요. 5.Qh5+ g6 6.fxg6 뒤 자연스러워 보이는 6...Nf6??는 바로 져요. 7.gxh7+가 디스커버드 체크이고, 7...Nxh5 8.Bg6로 메이트예요.', end='mate')])

O('st-george-defense', 'b', 'e4other', 'e4 a6', ['St. George Defense'],
  en=dict(name='St. George Defense', title='St. George Defense (1...a6): Lines and Stats by Rating',
          desc='The St. George Defense (1.e4 a6): 2.d4 b5 and the b7 bishop, plans for both sides, and how often each reply is played at your rating.',
          lead='1...a6 prepares ...b5 and ...Bb7, a queenside fianchetto with extra space. It became famous when Tony Miles beat world champion Anatoly Karpov with it in 1980, but it gives White the center for free.',
          white=['2.d4 b5 3.Nf3 Bb7 4.Bd3 is a simple setup: protect e4 and develop.',
                 '3.a4 or 3.c4 hits the b5 pawn at once and opens lines on the queenside.',
                 'Keep your center pawns supported; Black’s plan is to undermine them with ...c5 and ...e6.'],
          black=['After 2.d4 b5, ...Bb7, ...e6, ...c5 and ...Nf6 hit e4 and d4.',
                 'Watch the b5 pawn: against a4 or c4 be ready with ...b4 or ...bxc4.',
                 'It is a surprise weapon; much of its success comes from opponents who do not know what to do.'],
          club='Below 1200 White scores about 54% after 1...a6, but at 2000+ only about 49%. After 2.d4 b5, players below 2000 mostly play 3.Nf3, while at 2000+ the choices are spread between 3.Bd3, 3.Nf3, 3.c4 and 3.a4.'),
  ko=dict(name='세인트 조지 디펜스', title='세인트 조지 디펜스(1...a6): 수순과 레이팅별 응수',
          desc='세인트 조지 디펜스(1.e4 a6) 정리: 2.d4 b5와 b7 비숍, 양쪽 계획, 레이팅별로 많이 두는 응수.',
          lead='1...a6는 ...b5와 ...Bb7를 준비해요. 공간을 더 잡는 퀸 쪽 피앙케토예요. 1980년 토니 마일스가 세계 챔피언 아나톨리 카르포프를 이 수로 이겨서 유명해졌지만, 백에게 중앙을 그냥 내줘요.',
          white=['2.d4 b5 3.Nf3 Bb7 4.Bd3가 단순한 배치예요. e4를 지키고 전개해요.',
                 '3.a4나 3.c4는 바로 b5 폰을 쳐서 퀸 쪽 길을 열어요.',
                 '중앙 폰을 받쳐 둬요. 흑의 계획은 ...c5와 ...e6로 그 폰들을 흔드는 거예요.'],
          black=['2.d4 b5 뒤 ...Bb7, ...e6, ...c5, ...Nf6로 e4와 d4를 쳐요.',
                 'b5 폰을 살펴요. a4나 c4에는 ...b4나 ...bxc4를 준비해 둬요.',
                 '기습용 오프닝이에요. 성적의 상당 부분은 대처법을 모르는 상대에게서 나와요.'],
          club='1200 미만에서는 1...a6 뒤 백 점수가 54% 정도지만 2000 이상에서는 49% 정도예요. 2.d4 b5 뒤 2000 아래는 대부분 3.Nf3를 두고, 2000 이상은 3.Bd3, 3.Nf3, 3.c4, 3.a4로 고르게 나뉘어요.'),
  vars=[V('e4 a6 d4 b5 Nf3 Bb7 Bd3 e6 O-O c5 c3', '2.d4 b5 3.Nf3 Bb7 4.Bd3', 'The calm main line. Black hits d4 with ...c5 and develops with ...Nf6.',
          '2.d4 b5 3.Nf3 Bb7 4.Bd3', '차분한 주요 수순이에요. 흑은 ...c5로 d4를 치고 ...Nf6로 전개해요.'),
        V('e4 a6 d4 b5 a4 b4', '3.a4', 'White attacks b5 at once; after 3...b4 the pawn is safe but Black’s queenside is loose.',
          '3.a4', '백이 바로 b5를 쳐요. 3...b4면 폰은 안전하지만 흑 퀸 쪽이 헐거워져요.'),
        V('e4 a6 d4 b5 c4 bxc4 Bxc4', '3.c4', 'White trades the c-pawn for the b-pawn and develops fast; Black is left with an extra central pawn.',
          '3.c4', '백이 c폰과 b폰을 바꾸며 빨리 전개해요. 흑은 중앙 폰이 하나 더 많아져요.')],
  traps=[])

O('rare-defenses-to-e4', 'b', 'e4other', 'e4 f5',
  ['Duras Gambit', 'Borg Defense', 'Ware Defense', 'Goldsmith Defense', 'Barnes Defense', 'Fried Fox Defense', 'Carr Defense', 'Lemming Defense'],
  en=dict(name='Rare Defenses to 1.e4', title='Rare Defenses to 1.e4: 1...f5, 1...g5, 1...a5, 1...f6 and More',
          desc='Rare first replies to 1.e4: the Duras Gambit 1...f5, Borg 1...g5, Ware 1...a5, Goldsmith 1...h5, Barnes 1...f6, Carr 1...h6 and Lemming 1...Na6, with stats.',
          lead='These first replies do little for Black’s development or the center, which is why they are rare. None of them is lost, but each gives White an easy game: develop, take the center with d4, and look for checks against the loosened king.',
          white=['2.d4 is the best answer to almost all of them: take the whole center while Black does nothing for it.',
                 'Against 1...f5 and 1...f6, look for Qh5+ and Bc4 aimed at the loosened e8–h5 and a2–g8 diagonals.',
                 'Against 1...g5, hit the pawn with h4, or develop the c1 bishop toward it.'],
          black=['If you play one of these, know the one plan it serves, such as ...Bg7 after 1...g5.',
                 'Many of them turn into a Modern Defense or a Pirc with a move less.',
                 'They work best in fast games against an unprepared opponent.'],
          club='Below 1200 every reply on this page scores at least 53% for White, and the Lemming 1...Na6 scores about 72%. At 2000+ some come close to even: White scores about 48% against 1...h6 and about 50% against 1...h5. The most played is the Duras Gambit 1...f5, with about 18,000 games.'),
  ko=dict(name='1.e4에 드문 응수', title='1.e4에 드문 응수: 1...f5·1...g5·1...a5·1...f6 등',
          desc='1.e4에 대한 드문 첫 응수 정리: 두라스 갬빗 1...f5, 보그 1...g5, 웨어 1...a5, 골드스미스 1...h5, 반스 1...f6, 카 1...h6, 레밍 1...Na6, 레이팅별 통계.',
          lead='이 응수들은 흑의 전개나 중앙에 별 도움이 안 돼서 드물어요. 바로 지는 수는 없지만, 모두 백에게 편한 판을 줘요. 전개하고, d4로 중앙을 잡고, 헐거워진 킹을 향한 체크를 찾아요.',
          white=['거의 모두에 2.d4가 가장 좋은 응수예요. 흑이 중앙에 손을 쓰지 않는 동안 중앙을 다 가져요.',
                 '1...f5와 1...f6에는 헐거워진 e8–h5와 a2–g8 대각선을 노리는 Qh5+와 Bc4를 찾아요.',
                 '1...g5에는 h4로 폰을 치거나 c1 비숍을 그쪽으로 꺼내요.'],
          black=['이 수 가운데 하나를 둔다면 그 수가 돕는 계획 하나를 알아 둬요. 1...g5 뒤 ...Bg7 같은 거예요.',
                 '많은 경우 한 수 늦은 모던 디펜스나 피르츠가 돼요.',
                 '준비 안 된 상대와 빠른 판에서 가장 잘 통해요.'],
          club='1200 미만에서는 이 페이지의 모든 응수가 백 점수 53% 이상이고, 레밍 1...Na6는 72% 정도예요. 2000 이상에서는 거의 균형인 것도 있어요. 1...h6 상대로 백 점수가 48% 정도, 1...h5 상대로 50% 정도예요. 가장 많이 두는 건 두라스 갬빗 1...f5로 1만 8천 판 정도예요.'),
  vars=[V('e4 f5 exf5 Nf6', 'Duras Gambit, 1...f5', 'Black gives the f-pawn; after 2.exf5 White scores about 56%, and Qh5+ ideas are in the air.',
          '두라스 갬빗, 1...f5', '흑이 f폰을 줘요. 2.exf5 뒤 백 점수는 56% 정도이고, Qh5+ 수법을 늘 조심해야 해요.'),
        V('e4 g5 d4 Bg7', 'Borg Defense, 1...g5', 'A Grob with colors reversed: ...Bg7 hits d4, but the g5 pawn is loose. At 2000+ about three in four answer 2.d4.',
          '보그 디펜스, 1...g5', '색을 바꾼 그롭이에요. ...Bg7가 d4를 치지만 g5 폰이 헐거워요. 2000 이상에서는 넷에 셋 정도가 2.d4로 받아요.'),
        V('e4 a5', 'Ware Defense, 1...a5', 'The rook can come out via a6, but White scores about 58% after it.',
          '웨어 디펜스, 1...a5', '룩이 a6로 나올 수 있지만, 이 수 뒤 백 점수는 58% 정도예요.'),
        V('e4 h5', 'Goldsmith Defense, 1...h5', 'Below 1200 White scores about 57% against it; at 2000+ about 50%.',
          '골드스미스 디펜스, 1...h5', '1200 미만에서는 백 점수가 57% 정도이고, 2000 이상에서는 50% 정도예요.'),
        V('e4 f6', 'Barnes Defense, 1...f6', 'The f-pawn takes the knight’s best square and opens the king’s diagonal. White scores about 59%.',
          '반스 디펜스, 1...f6', 'f폰이 나이트의 가장 좋은 칸을 빼앗고 킹의 대각선을 열어요. 백 점수는 59% 정도예요.'),
        V('e4 f6 d4 Kf7', 'Fried Fox, 2...Kf7', 'The king walks to f7 on move two. White scores about 58% after it.',
          '프라이드 폭스, 2...Kf7', '둘째 수에 킹이 f7로 걸어가요. 이 수 뒤 백 점수는 58% 정도예요.'),
        V('e4 h6', 'Carr Defense, 1...h6', 'A waiting move that often turns into a Modern; below 1200 White scores about 59%, at 2000+ about 48%.',
          '카 디펜스, 1...h6', '기다리는 수로, 모던이 되는 일이 많아요. 1200 미만에서는 백 점수가 59% 정도, 2000 이상에서는 48% 정도예요.'),
        V('e4 Na6', 'Lemming Defense, 1...Na6', 'The knight goes to the rim. White scores about 65% overall and about 72% below 1200, the worst result on this page.',
          '레밍 디펜스, 1...Na6', '나이트가 가장자리로 가요. 전체 백 점수는 65% 정도, 1200 미만에서는 72% 정도로 이 페이지에서 가장 나빠요.')],
  traps=[], hub=True)

