O('english-opening', 'w', 'flank', 'c4', ['English Opening', 'English Orangutan'],
  en=dict(name='English Opening', title='English Opening: Main Setups, Plans and Stats by Rating',
          desc='The English Opening (1.c4): the Reversed Sicilian, Symmetrical and Anglo-Indian setups, plans for both sides and real reply rates by rating.',
          lead='1.c4 controls d5 from the side, like a Sicilian with an extra tempo. White usually plays g3, Bg2 and Nc3 and fights for the light squares. It is flexible and can transpose into many 1.d4 openings.',
          white=['The Botvinnik/closed setup: g3, Bg2, Nc3, e4 or e3, Nge2.',
                 'Against 1...e5 (Reversed Sicilian) your bishop on g2 pressures d5 and b7.',
                 'Queenside expansion with Rb1, b4–b5 is a typical plan.'],
          black=['1...e5 takes the center; 1...c5 copies; 1...Nf6 keeps options open.',
                 'Against White’s g3 setups, a solid ...d5 or ...e5 center works well.',
                 'Do not let White’s g2 bishop and Nc3 dominate d5.'],
          club='Below 2000 the English is far less common than 1.e4 or 1.d4, so many Black players are not prepared. Learning one setup (g3, Bg2, Nc3) is enough to start.'),
  ko=dict(name='잉글리시 오프닝', title='잉글리시 오프닝: 주요 배치·계획·레이팅별 응수',
          desc='잉글리시 오프닝(1.c4) 정리: 역 시실리안, 대칭, 앵글로 인디언 배치, 양쪽 계획과 레이팅별 실제 응수 비율.',
          lead='1.c4는 옆에서 d5를 다스려요. 한 수 더 둔 시실리안 같아요. 백은 보통 g3, Bg2, Nc3로 흰 칸을 다퉈요. 유연해서 여러 1.d4 오프닝으로 넘어갈 수 있어요.',
          white=['보트비닉·닫힌 배치: g3, Bg2, Nc3, e4나 e3, Nge2.',
                 '1...e5(역 시실리안)에는 g2 비숍이 d5와 b7을 압박해요.',
                 'Rb1, b4–b5로 퀸 쪽을 넓히는 게 흔한 계획이에요.'],
          black=['1...e5는 중앙을 잡고, 1...c5는 따라 하고, 1...Nf6는 선택지를 남겨요.',
                 '백의 g3 배치에는 단단한 ...d5나 ...e5 중앙이 잘 통해요.',
                 '백의 g2 비숍과 Nc3가 d5를 지배하게 두지 말아요.'],
          club='2000 아래에선 잉글리시가 1.e4나 1.d4보다 훨씬 드물어서 준비 안 된 흑이 많아요. 배치 하나(g3, Bg2, Nc3)로 시작하면 충분해요.'),
  vars=[V('c4 e5 Nc3 Nf6 g3 d5 cxd5 Nxd5 Bg2', 'Reversed Sicilian, ...d5', 'A Dragon with colors reversed and an extra tempo for White.',
          '역 시실리안, ...d5', '색을 바꾸고 백이 한 수 더 둔 드래곤이에요.'),
        V('c4 c5 Nc3 Nc6 g3 g6 Bg2 Bg7', 'Symmetrical English', 'Both sides fianchetto. Slow, positional maneuvering.',
          '대칭 잉글리시', '둘 다 피앙케토해요. 느린 포지션 싸움이에요.'),
        V('c4 Nf6 Nc3 e5 Nf3 Nc6', 'Four Knights English', 'White plays g3 or e3; Black answers ...Bb4 or ...d5.',
          '포 나이츠 잉글리시', '백은 g3나 e3, 흑은 ...Bb4나 ...d5.'),
        V('Nf3 Nf6 c4 e6 g3 d5 Bg2', 'Neo-Catalan, 1.Nf3 and 3.g3', 'A Catalan setup without d4: White keeps the d-pawn back and can choose d4 or b3 later. About seven in ten of these games are played at 2000+.',
          '네오 카탈란, 1.Nf3와 3.g3', 'd4 없는 카탈란 배치예요. 백은 d폰을 뒤에 두고 나중에 d4나 b3를 골라요. 이 판의 열에 일곱 정도가 2000 이상에서 나와요.'),
        V('c4 e6 Nc3 d5 d4', 'Transposing to 1.d4', 'A common way the English turns into a Queen’s Gambit Declined.',
          '1.d4로 넘어가기', '잉글리시가 퀸스 갬빗 거절로 바뀌는 흔한 길이에요.')],
  traps=[])

O('reti-opening', 'w', 'flank', 'Nf3', ['Zukertort Opening', 'Réti Opening'],
  en=dict(name='Réti Opening (1.Nf3)', title='Réti Opening and 1.Nf3: Setups, Plans and Stats by Rating',
          desc='1.Nf3 (Zukertort/Réti): the Réti with c4, the King’s Indian Attack and transpositions to 1.d4, with plans and real reply rates by rating.',
          lead='1.Nf3 develops a knight and waits to see Black’s setup. White can choose a Réti (c4 and g3), a King’s Indian Attack (g3, d3, e4) or simply transpose to a 1.d4 opening.',
          white=['Réti: c4 and g3 attack d5 from the side; Bg2 rakes the long diagonal.',
                 'King’s Indian Attack: g3, Bg2, O-O, d3, Nbd2 and e4 against almost anything.',
                 'With d4 you can reach a London, Queen’s Gambit or Catalan on your own terms.'],
          black=['1...d5 and 1...Nf6 are the most flexible replies.',
                 'Against the Réti, ...d4 grabs space; ...c6 and ...Bf5 or ...Bg4 is a solid setup.',
                 '...c5 and ...Nc6 can lead to a Sicilian-style game if White plays e4.'],
          club='1.Nf3 is popular with players who want a system rather than lines. At every rating level here, 1...d5 is Black’s most common answer, so the KIA or Réti setups cover most games.'),
  ko=dict(name='레티 오프닝(1.Nf3)', title='레티 오프닝·1.Nf3: 배치·계획·레이팅별 응수',
          desc='1.Nf3(주커토르트·레티) 정리: c4를 둔 레티, 킹스 인디언 어택, 1.d4로 넘어가기, 계획과 레이팅별 실제 응수 비율.',
          lead='1.Nf3는 나이트를 전개하고 흑 배치를 지켜봐요. 백은 레티(c4와 g3), 킹스 인디언 어택(g3, d3, e4), 아니면 1.d4 오프닝으로 넘어갈 수 있어요.',
          white=['레티: c4와 g3로 옆에서 d5를 쳐요. Bg2가 긴 대각선을 쓸어요.',
                 '킹스 인디언 어택: 상대가 뭘 두든 g3, Bg2, O-O, d3, Nbd2, e4.',
                 'd4를 두면 런던, 퀸스 갬빗, 카탈란으로 내 뜻대로 넘어가요.'],
          black=['1...d5와 1...Nf6가 가장 유연한 응수예요.',
                 '레티에는 ...d4로 공간을 잡거나, ...c6와 ...Bf5나 ...Bg4로 단단히.',
                 '백이 e4를 두면 ...c5, ...Nc6로 시실리안 같은 판이 될 수 있어요.'],
          club='1.Nf3는 수순보다 체계를 원하는 사람들이 좋아해요. 모든 레이팅대에서 흑은 1...d5를 가장 많이 두니, KIA나 레티 배치면 판 대부분을 받아요.'),
  vars=[V('Nf3 d5 c4 d4', 'Réti, 2...d4', 'Black grabs space; White answers e3 or b4 and attacks the d4 pawn.',
          '레티, 2...d4', '흑이 공간을 잡아요. 백은 e3나 b4로 d4 폰을 공격해요.'),
        V('Nf3 d5 c4 e6 g3 Nf6 Bg2', 'Réti with ...e6', 'Often becomes a Catalan or a QGD with g3.',
          '...e6 레티', '카탈란이나 g3를 둔 퀸스 갬빗 거절로 자주 바뀌어요.'),
        V('Nf3 d5 g3 Nf6 Bg2 c6 O-O Bg4 d3', 'King’s Indian Attack', 'White builds g3, Bg2, d3, Nbd2 and e4. Black chooses ...Bg4 or ...Bf5. It has its own guide.',
          '킹스 인디언 어택', '백이 g3, Bg2, d3, Nbd2, e4를 쌓아요. 흑은 ...Bg4나 ...Bf5. 따로 해설이 있어요.'),
        V('Nf3 Nf6 c4 g6 Nc3 Bg7', 'Against a King’s Indian setup', 'White can play e4 (a KID) or g3 (an English).',
          '킹스 인디언 배치 상대', '백은 e4(킹스 인디언)나 g3(잉글리시).')],
  traps=[])

O('kings-indian-attack', 'w', 'flank', 'Nf3 d5 g3', ["King's Indian Attack", "French Defense: King's Indian Attack"],
  en=dict(name='King’s Indian Attack', title='King’s Indian Attack (KIA): Setup, Plans and Stats by Rating',
          desc='The King’s Indian Attack: Nf3, g3, Bg2, O-O, d3, Nbd2 and e4 against ...d5, the French and the Sicilian, plans for both sides and reply rates by rating.',
          lead='The King’s Indian Attack is a setup more than a line: Nf3, g3, Bg2, O-O, d3, Nbd2 and e4, played against almost anything. It is the King’s Indian Defense with colors reversed and an extra move, and White often follows with e5 and a kingside attack.',
          white=['Build the setup first; the e4 push, and later e5, decide the plan.',
                 'Against ...e6 and ...c5 (French or Sicilian setups), e5 gains space, and Re1, Nf1, h4 and Bf4 build the kingside attack.',
                 'Against ...c6 with ...Bg4 or ...Bf5, play h3 or e4 to ask the bishop where it is going.'],
          black=['...d5, ...Nf6, ...c5 and ...Nc6 claim space; queenside play with ...b5–b4 races White’s kingside attack.',
                 'When you can, develop the c8 bishop before ...e6: ...Bg4 or ...Bf5 suits this setup.',
                 'If White plays e5, hit the pawn chain with ...f6 or ...c5–c4.'],
          club='White scores about 54% after 1.Nf3 d5 2.g3, and about 55% at 2000+, better than most first-move setups. Below 1200 the most common reply is 2...Nc6, at 2000+ 2...Nf6. Against the French (1.e4 e6 2.d3 d5 3.Nd2) White also scores about 55%.'),
  ko=dict(name='킹스 인디언 어택', title='킹스 인디언 어택(KIA): 배치·계획·레이팅별 응수',
          desc='킹스 인디언 어택 정리: ...d5, 프렌치, 시실리안 상대로 두는 Nf3, g3, Bg2, O-O, d3, Nbd2, e4 배치, 양쪽 계획, 레이팅별로 많이 두는 응수.',
          lead='킹스 인디언 어택은 수순보다 배치예요. Nf3, g3, Bg2, O-O, d3, Nbd2, e4를 상대가 무엇을 두든 둬요. 색을 바꾸고 한 수 더 둔 킹스 인디언 디펜스이고, 백은 흔히 e5를 민 뒤 킹 쪽을 공격해요.',
          white=['먼저 배치를 갖춰요. e4 밀기와 나중의 e5가 계획을 정해요.',
                 '...e6와 ...c5(프렌치나 시실리안 배치)에는 e5로 공간을 잡고 Re1, Nf1, h4, Bf4로 킹 쪽 공격을 쌓아요.',
                 '...c6에 ...Bg4나 ...Bf5에는 h3나 e4로 비숍이 어디로 갈지 물어요.'],
          black=['...d5, ...Nf6, ...c5, ...Nc6로 공간을 잡아요. ...b5–b4로 가는 퀸 쪽 반격이 백의 킹 쪽 공격과 경주해요.',
                 '할 수 있으면 ...e6 전에 c8 비숍을 꺼내요. 이 배치에는 ...Bg4나 ...Bf5가 잘 맞아요.',
                 '백이 e5를 밀면 ...f6나 ...c5–c4로 폰 사슬을 쳐요.'],
          club='1.Nf3 d5 2.g3 뒤 백 점수는 54% 정도, 2000 이상에서는 55% 정도로 첫 수 배치 대부분보다 높아요. 1200 미만에서는 2...Nc6가, 2000 이상에서는 2...Nf6가 가장 많은 응수예요. 프렌치 상대(1.e4 e6 2.d3 d5 3.Nd2)로도 백 점수가 55% 정도예요.'),
  vars=[V('Nf3 d5 g3 Nf6 Bg2 c6 O-O Bg4 d3 Nbd7 Nbd2 e5 e4', 'Against ...c6 and ...Bg4', 'Black builds a solid center with ...c6, ...Bg4, ...Nbd7 and ...e5; White plays e4 and later h3.',
          '...c6와 ...Bg4 상대', '흑이 ...c6, ...Bg4, ...Nbd7, ...e5로 단단한 중앙을 세워요. 백은 e4, 나중에 h3를 둬요.'),
        V('Nf3 d5 g3 c5 Bg2 Nc6 O-O e5 d3', 'Against the big center, ...c5 and ...e5', 'Black grabs space; White plays e4, Nbd2 and Nc4 or c3, as in a King’s Indian with colors reversed.',
          '큰 중앙 ...c5와 ...e5 상대', '흑이 공간을 잡아요. 백은 색을 바꾼 킹스 인디언처럼 e4, Nbd2, 그리고 Nc4나 c3를 둬요.'),
        V('e4 e6 d3 d5 Nd2 Nf6 Ngf3 c5 g3 Nc6 Bg2 Be7 O-O O-O', 'Against the French, 2.d3', 'The classic King’s Indian Attack: White plays Re1 and e5, then attacks with Nf1, h4 and Bf4.',
          '프렌치 상대, 2.d3', '고전 킹스 인디언 어택이에요. 백은 Re1과 e5를 둔 뒤 Nf1, h4, Bf4로 공격해요.'),
        V('e4 c5 Nf3 e6 d3 Nc6 g3', 'Against the Sicilian, 3.d3', 'White avoids open Sicilian theory and builds the same setup.',
          '시실리안 상대, 3.d3', '백이 오픈 시실리안 이론을 피하고 같은 배치를 쌓아요.'),
        V('Nf3 d5 g3 Nc6 d4', 'Against 2...Nc6, 3.d4', 'At 2000+ about a third of players switch to d4 here, because ...e5 would otherwise give Black a big center.',
          '2...Nc6 상대, 3.d4', '2000 이상에서는 셋에 하나 정도가 여기서 d4로 바꿔요. 그러지 않으면 ...e5로 흑이 큰 중앙을 얻기 때문이에요.')],
  traps=[])

O('bird-opening', 'w', 'flank', 'f4', ['Bird Opening'],
  en=dict(name='Bird Opening', title='Bird Opening (1.f4): From’s Gambit, Setups and Stats by Rating',
          desc='The Bird Opening (1.f4): setups against 1...d5, From’s Gambit 1...e5 and its mate trap, the Williams Gambit 2.e4, plans and reply rates by rating.',
          lead='1.f4 grabs e5 and prepares a kingside setup, like a Dutch Defense with colors reversed and an extra move. It loosens the e1–h4 diagonal a little, and From’s Gambit 1...e5 tries to exploit exactly that.',
          white=['Against 1...d5, Nf3, e3, Be2 or b3 with Bb2, and O-O is the classic setup; Ne5 and Qe1–h4 can follow.',
                 'Against From’s Gambit, 2.fxe5 d6 3.exd6 Bxd6 4.Nf3 is the safe line: with the f-pawn gone, never allow ...Qh4+.',
                 'Keep the e5 square: a knight there with f4 behind it is the heart of the Bird.'],
          black=['1...d5 with ...Nf6, ...g6 and ...Bg7, or ...Bg4, is solid against any setup.',
                 'From’s Gambit 1...e5 is sharp: after 4.Nf3 g5 Black throws the g-pawn at White’s king.',
                 'Aim at e4, which the f-pawn can no longer guard from f3, and contest e5 with ...Nc6 and ...e5.'],
          club='1...d5 is the most common answer at every level, about four games in ten. From’s Gambit comes in about one game in ten, and at 2000+ about four in five take with 2.fxe5. White scores about 52% after 1.f4 overall, but only about 49% below 1200.'),
  ko=dict(name='버드 오프닝', title='버드 오프닝(1.f4): 프롬 갬빗·배치·레이팅별 응수',
          desc='버드 오프닝(1.f4) 정리: 1...d5 상대 배치, 프롬 갬빗 1...e5와 메이트 함정, 윌리엄스 갬빗 2.e4, 양쪽 계획, 레이팅별로 많이 두는 응수.',
          lead='1.f4는 e5를 잡고 킹 쪽 배치를 준비해요. 색을 바꾸고 한 수 더 둔 더치 디펜스 같아요. e1–h4 대각선이 조금 헐거워지는데, 프롬 갬빗 1...e5가 바로 그 점을 노려요.',
          white=['1...d5에는 Nf3, e3, Be2나 b3와 Bb2, 그리고 O-O가 고전 배치예요. 그 뒤 Ne5와 Qe1–h4가 이어질 수 있어요.',
                 '프롬 갬빗에는 2.fxe5 d6 3.exd6 Bxd6 4.Nf3가 안전한 수순이에요. f폰이 없으니 ...Qh4+를 절대 허락하지 말아요.',
                 'e5 칸을 지켜요. f4 뒤에 받친 e5 나이트가 버드의 핵심이에요.'],
          black=['1...d5에 ...Nf6, ...g6, ...Bg7, 또는 ...Bg4는 어떤 배치에도 단단해요.',
                 '프롬 갬빗 1...e5는 날카로워요. 4.Nf3 g5 뒤 흑은 g폰을 백 킹 쪽으로 던져요.',
                 'f폰이 f3에서 지킬 수 없게 된 e4를 노리고, ...Nc6와 ...e5로 e5를 다퉈요.'],
          club='모든 레이팅대에서 1...d5가 가장 많은 응수이고 열에 넷 정도예요. 프롬 갬빗은 열 판에 한 판꼴이고, 2000 이상에서는 다섯에 넷 정도가 2.fxe5로 받아요. 1.f4 뒤 전체 백 점수는 52% 정도지만 1200 미만에서는 49% 정도예요.'),
  vars=[V('f4 d5 Nf3 Nf6 e3 g6 Be2 Bg7 O-O O-O', 'Dutch Variation, 1...d5', 'A reversed Dutch setup; White follows with b3, Bb2, Qe1 and Ne5.',
          '더치 변화, 1...d5', '색을 바꾼 더치 배치예요. 백은 b3, Bb2, Qe1, Ne5로 이어 가요.'),
        V('f4 d5 Nf3 Nf6 e3 Bg4', '1...d5 with ...Bg4', 'The bishop pins the f3 knight; Be2, or b3 with Bb2, are the usual answers.',
          '1...d5와 ...Bg4', '비숍이 f3 나이트를 묶어요. Be2, 또는 b3와 Bb2가 흔한 응수예요.'),
        V('f4 Nf6 Nf3 g6 b3 Bg7 Bb2', 'Against ...g6', 'Black fianchettoes; White mirrors with b3 and Bb2 and fights over e5.',
          '...g6 상대', '흑이 피앙케토하면 백도 b3와 Bb2로 맞서며 e5를 다퉈요.'),
        V('f4 e5 fxe5 d6 exd6 Bxd6 Nf3 g5', 'From’s Gambit, Lasker 4...g5', 'Black gives a second pawn to open the g-file; White answers 5.g3 or 5.d4.',
          '프롬 갬빗, 라스커 4...g5', '흑이 폰을 하나 더 주고 g파일을 열어요. 백은 5.g3나 5.d4로 받아요.'),
        V('f4 d5 e4', 'Williams Gambit, 2.e4', 'White gives the e-pawn for quick play. White scores only about 46% after it, and about 41% below 1200.',
          '윌리엄스 갬빗, 2.e4', '백이 e폰을 주고 빠른 판을 노려요. 이 수 뒤 백 점수는 46% 정도, 1200 미만에서는 41% 정도뿐이에요.')],
  traps=[TR('f4 e5 fxe5 d6 exd6 Bxd6 Nc3 Qh4+ g3 Qxg3+ hxg3 Bxg3#', 'From’s Gambit: 4.Nc3?? Qh4+',
            'After 3...Bxd6 White has to stop ...Qh4+. The natural 4.Nc3?? allows 4...Qh4+ 5.g3 Qxg3+ 6.hxg3 Bxg3 mate. 4.Nf3 covers h4 and is the main move.',
            '프롬 갬빗: 4.Nc3?? Qh4+', '3...Bxd6 뒤 백은 ...Qh4+를 막아야 해요. 자연스러운 4.Nc3??면 4...Qh4+ 5.g3 Qxg3+ 6.hxg3 Bxg3로 메이트예요. h4를 막는 4.Nf3가 주요 수예요.', end='mate')])

O('nimzo-larsen-attack', 'w', 'flank', 'b3', ['Nimzo-Larsen Attack'],
  en=dict(name='Nimzo-Larsen Attack', title='Nimzo-Larsen Attack (1.b3): Setups, Plans and Stats by Rating',
          desc='The Nimzo-Larsen Attack (1.b3): 1...e5 2.Bb2 Nc6, 1...d5 and 1...Nf6 setups, the b2 bishop against e5, plans for both sides and reply rates by rating.',
          lead='1.b3 prepares Bb2, which aims down the long diagonal at e5 and g7. White keeps the center pawns back and decides later between e3 with f4, c4, or g3. It is flexible and rarely met with prepared theory.',
          white=['Bb2 first, then e3, Nf3 and Be2 or Bb5; f4 grabs e5 when Black has played ...e5.',
                 'Against 1...e5 2.Bb2 Nc6, 3.e3 with Bb5 pins the knight that guards e5.',
                 'Against ...g6 and ...Bg7 the long diagonal is blocked; switch to c4 with d3 or g3.'],
          black=['1...e5 takes the center and blocks the b2 bishop; ...Nc6, ...d5 and ...Bd6 build a big center.',
                 '1...d5 with ...Nf6, ...e6 or ...Bf5 is a quiet, solid answer.',
                 '...g6 and ...Bg7 meets the b2 bishop head-on; White scores only about 48% against it here.'],
          club='Below 1200, about 45% answer 1.b3 with 1...e5; at 2000+ replies spread out between 1...d5, 1...e5 and 1...Nf6. After 1...e5 2.Bb2 Nc6 3.e3 d5 4.Bb5 Bd6, White scores about 56%, and at 2000+ about seven in ten push 5.f4.'),
  ko=dict(name='님조-라르센 어택', title='님조-라르센 어택(1.b3): 배치·계획·레이팅별 응수',
          desc='님조-라르센 어택(1.b3) 정리: 1...e5 2.Bb2 Nc6, 1...d5, 1...Nf6 배치, e5를 겨누는 b2 비숍, 양쪽 계획, 레이팅별로 많이 두는 응수.',
          lead='1.b3는 Bb2를 준비해요. 이 비숍은 긴 대각선을 따라 e5와 g7을 겨눠요. 백은 중앙 폰을 뒤에 두고, e3와 f4, c4, g3 가운데 무엇을 할지 나중에 정해요. 유연하고, 준비된 이론으로 맞서는 상대가 드물어요.',
          white=['먼저 Bb2, 그다음 e3, Nf3, Be2나 Bb5. 흑이 ...e5를 뒀다면 f4로 e5를 잡아요.',
                 '1...e5 2.Bb2 Nc6에는 3.e3와 Bb5로 e5를 지키는 나이트를 묶어요.',
                 '...g6와 ...Bg7에는 긴 대각선이 막혀요. c4와 d3나 g3로 바꿔요.'],
          black=['1...e5는 중앙을 잡고 b2 비숍을 막아요. ...Nc6, ...d5, ...Bd6로 큰 중앙을 세워요.',
                 '1...d5에 ...Nf6, ...e6나 ...Bf5는 조용하고 단단한 응수예요.',
                 '...g6와 ...Bg7는 b2 비숍과 정면으로 맞서요. 여기서 이 배치 상대로 백 점수는 48% 정도뿐이에요.'],
          club='1200 미만에서는 45% 정도가 1.b3에 1...e5로 받고, 2000 이상에서는 1...d5, 1...e5, 1...Nf6로 고르게 나뉘어요. 1...e5 2.Bb2 Nc6 3.e3 d5 4.Bb5 Bd6 뒤 백 점수는 56% 정도이고, 2000 이상에서는 열에 일곱 정도가 5.f4를 밀어요.'),
  vars=[V('b3 e5 Bb2 Nc6 e3 d5 Bb5 Bd6', 'Modern, 1...e5 2.Bb2 Nc6', 'The main line. White pins the c6 knight and plans f4 or Nf3 to attack e5.',
          '모던, 1...e5 2.Bb2 Nc6', '주요 수순이에요. 백은 c6 나이트를 묶고 f4나 Nf3로 e5를 칠 계획이에요.'),
        V('b3 d5 Bb2 Nf6 e3 Bf5 Nf3 e6', 'Classical, 1...d5', 'Black develops the c8 bishop first and builds a London-like setup; White plays c4 or d4 later.',
          '클래시컬, 1...d5', '흑이 c8 비숍을 먼저 꺼내고 런던 같은 배치를 세워요. 백은 나중에 c4나 d4를 둬요.'),
        V('b3 Nf6 Bb2 g6 g3 Bg7 Bg2 O-O', 'Indian, 1...Nf6 with ...g6', 'Both sides fianchetto; the long diagonals are shut and the game is slow.',
          '인디언, 1...Nf6와 ...g6', '둘 다 피앙케토해요. 긴 대각선이 막히고 판이 느려져요.'),
        V('b3 e5 Bb2 Nc6 c4 Nf6 e3 d5 cxd5 Nxd5 a3', 'English setup, 3.c4', 'A Sicilian with colors reversed: White aims at d5 and the long diagonal.',
          '잉글리시 배치, 3.c4', '색을 바꾼 시실리안이에요. 백은 d5와 긴 대각선을 노려요.')],
  traps=[])

O('hungarian-opening', 'w', 'flank', 'g3', ['Hungarian Opening', 'Lasker Simul Special'],
  en=dict(name='Hungarian Opening (1.g3)', title='Hungarian Opening (1.g3): Setups, Transpositions and Stats',
          desc='The Hungarian Opening (1.g3): the Bg2 fianchetto, plans against 1...e5 and 1...d5, transpositions to the English and the King’s Indian Attack, and reply rates.',
          lead='1.g3 prepares Bg2 and commits to nothing else. White can turn it into an English with c4, a King’s Indian Attack with Nf3, d3 and e4, or a Modern Defense with colors reversed. It is a move-order tool more than an opening of its own.',
          white=['Bg2 first; then choose between c4 (English), Nf3 and d3 (King’s Indian Attack) or d4.',
                 'Against 1...e5 and 2...d5, d3 with Nf3, or c4, hits the center Black has built.',
                 'Against 1...d5 with ...c6 and ...Bf5 or ...Bg4, play d3 and e4, or c4, to open the g2 bishop’s diagonal.'],
          black=['Take the center: 1...e5 with ...d5, or 1...d5 with ...e5, is the most direct reply.',
                 '...c6 with ...Bf5 or ...Bg4 blunts the g2 bishop.',
                 'Copying with ...g6 and ...Bg7 gives a slow, symmetrical game.'],
          club='Below 1200, 1...e5 is the most common answer (44%); at 2000+ 1...d5 leads at 36%, with 1...Nf6 next. After 1...e5 2.Bg2 d5, players at 2000+ choose 3.d3 or 3.c4 in about half the games. White scores about 51% after 1.g3.'),
  ko=dict(name='헝가리안 오프닝(1.g3)', title='헝가리안 오프닝(1.g3): 배치·다른 오프닝으로 넘어가기·응수',
          desc='헝가리안 오프닝(1.g3) 정리: Bg2 피앙케토, 1...e5와 1...d5 상대로 둘 수, 잉글리시와 킹스 인디언 어택으로 넘어가기, 레이팅별로 많이 두는 응수.',
          lead='1.g3는 Bg2를 준비할 뿐 다른 것은 아직 정하지 않아요. 백은 c4로 잉글리시, Nf3·d3·e4로 킹스 인디언 어택, 또는 색을 바꾼 모던 디펜스로 갈 수 있어요. 따로 선 오프닝이라기보다 수순을 고르는 도구예요.',
          white=['먼저 Bg2, 그다음 c4(잉글리시), Nf3와 d3(킹스 인디언 어택), d4 가운데 골라요.',
                 '1...e5와 2...d5에는 d3와 Nf3, 또는 c4로 흑이 세운 중앙을 쳐요.',
                 '1...d5에 ...c6와 ...Bf5나 ...Bg4에는 d3와 e4, 또는 c4로 g2 비숍의 대각선을 열어요.'],
          black=['중앙을 잡아요. 1...e5와 ...d5, 또는 1...d5와 ...e5가 가장 곧은 응수예요.',
                 '...c6와 ...Bf5나 ...Bg4는 g2 비숍을 무디게 해요.',
                 '...g6와 ...Bg7로 따라 하면 느리고 대칭인 판이 돼요.'],
          club='1200 미만에서는 1...e5가 가장 많은 응수(44%)이고, 2000 이상에서는 1...d5가 36%로 앞서고 1...Nf6가 뒤를 이어요. 1...e5 2.Bg2 d5 뒤 2000 이상에서는 절반 정도가 3.d3나 3.c4를 골라요. 1.g3 뒤 백 점수는 51% 정도예요.'),
  vars=[V('g3 e5 Bg2 d5 d3 Nf6 Nf3 Nc6 O-O Be7 c4', 'Against 1...e5 and 2...d5', 'Black builds a big center; White plays d3, Nf3, O-O and c4 to undermine it, like a Pirc with colors reversed.',
          '1...e5와 2...d5 상대', '흑이 큰 중앙을 세워요. 백은 색을 바꾼 피르츠처럼 d3, Nf3, O-O, c4로 그 중앙을 흔들어요.'),
        V('g3 e5 Bg2 d5 b3', 'Double fianchetto, 3.b3', 'White adds Bb2 to hit e5 from the other side; it is the second most common third move.',
          '이중 피앙케토, 3.b3', '백이 Bb2를 더해 반대쪽에서 e5를 쳐요. 두 번째로 많이 두는 셋째 수예요.'),
        V('g3 d5 Bg2 Nf6 Nf3 c6 O-O Bg4 d3', 'Against 1...d5 with ...c6 and ...Bg4', 'This becomes a King’s Indian Attack, which has its own guide.',
          '1...d5에 ...c6와 ...Bg4 상대', '킹스 인디언 어택이 돼요. 따로 해설이 있어요.'),
        V('g3 g6 Bg2 Bg7 c4 c5 Nc3 Nc6', 'Symmetrical, 1...g6', 'Both sides fianchetto; with c4 it becomes a Symmetrical English.',
          '대칭, 1...g6', '둘 다 피앙케토해요. c4를 두면 대칭 잉글리시가 돼요.')],
  traps=[])

O('polish-opening', 'w', 'flank', 'b4', ['Polish Opening'],
  en=dict(name='Polish Opening (1.b4)', title='Polish Opening (1.b4): 1...e5, 1...d5, a Trap and Stats by Rating',
          desc='The Polish Opening (1.b4): 1...e5 2.Bb2 with ...Bxb4 or ...d6, the Bugayev 2.a3, 1...d5, the 3...Nc6? trap and reply rates by rating.',
          lead='1.b4 grabs queenside space and prepares Bb2 toward e5 and g7. It is also known as the Sokolsky or the Orangutan. The b4 pawn is loose, so Black can gain time by attacking it, but the opening sets real problems for players who rarely meet it.',
          white=['Against 1...e5, 2.Bb2 hits e5 at once; after 2...Bxb4 3.Bxe5 White has traded the b-pawn for the e-pawn.',
                 'a3 or b5 keeps the pawn when Black attacks it with ...a5, or with ...c6 and ...Qb6.',
                 'e3, Nf3, c4 and Be2 complete the setup; the b2 bishop is your key piece.'],
          black=['1...e5 2.Bb2 Bxb4 is the most direct line; after 3.Bxe5, play 3...Nf6 to block the diagonal.',
                 '1...e5 with ...d6 or ...f6 keeps the center and blunts the b2 bishop.',
                 '1...d5 with ...Nf6, ...e6 or ...Bf5 is a solid, quiet answer.'],
          club='After 1...e5 2.Bb2, players at 2000+ most often take with 2...Bxb4, but below 1200 2...Nc6 is the top reply. After 2...Bxb4 3.Bxe5, nine in ten at 2000+ play 3...Nf6, while below 1200 only about one in eight does, and White scores about 67% there. White scores about 53% after 1.b4 overall.'),
  ko=dict(name='폴리시 오프닝(1.b4)', title='폴리시 오프닝(1.b4): 1...e5·1...d5·함정, 레이팅별 응수',
          desc='폴리시 오프닝(1.b4) 정리: 1...e5 2.Bb2와 ...Bxb4·...d6, 부가예프 2.a3, 1...d5, 3...Nc6? 함정, 레이팅별로 많이 두는 응수.',
          lead='1.b4는 퀸 쪽 공간을 잡고 e5와 g7을 겨눌 Bb2를 준비해요. b4 폰이 헐거워서 흑은 그 폰을 치며 시간을 벌 수 있지만, 이 오프닝을 자주 만나지 않는 사람에게는 진짜 문제를 내요.',
          white=['1...e5에는 2.Bb2로 바로 e5를 쳐요. 2...Bxb4 3.Bxe5 뒤엔 b폰과 e폰을 바꾼 셈이에요.',
                 '흑이 ...a5, 또는 ...c6와 ...Qb6로 폰을 치면 a3나 b5로 지켜요.',
                 'e3, Nf3, c4, Be2로 배치를 마쳐요. b2 비숍이 가장 중요한 말이에요.'],
          black=['1...e5 2.Bb2 Bxb4가 가장 곧은 수순이에요. 3.Bxe5 뒤엔 3...Nf6로 대각선을 막아요.',
                 '1...e5에 ...d6나 ...f6는 중앙을 지키고 b2 비숍을 무디게 해요.',
                 '1...d5에 ...Nf6, ...e6나 ...Bf5는 단단하고 조용한 응수예요.'],
          club='1...e5 2.Bb2 뒤 2000 이상에서는 2...Bxb4가 가장 많지만, 1200 미만에서는 2...Nc6가 가장 많아요. 2...Bxb4 3.Bxe5 뒤 2000 이상에서는 열에 아홉이 3...Nf6를 두는데, 1200 미만에서는 여덟에 하나 정도뿐이고 거기서 백 점수는 67% 정도예요. 1.b4 뒤 전체 백 점수는 53% 정도예요.'),
  vars=[V('b4 e5 Bb2 Bxb4 Bxe5 Nf6 c4', '1...e5 2.Bb2 Bxb4', 'Black takes the b-pawn and White takes the e-pawn. Black develops with ...O-O and ...d6 or ...Nc6.',
          '1...e5 2.Bb2 Bxb4', '흑은 b폰, 백은 e폰을 가져가요. 흑은 ...O-O와 ...d6나 ...Nc6로 전개해요.'),
        V('b4 e5 Bb2 d6 c4 Nf6 e3 g6', '2...d6', 'Black holds e5 with a pawn and fianchettoes; White expands on the queenside.',
          '2...d6', '흑이 폰으로 e5를 지키고 피앙케토해요. 백은 퀸 쪽을 넓혀요.'),
        V('b4 e5 Bb2 f6 b5 d5 e3 Be6', '2...f6', 'Black holds e5 with the f-pawn and builds a big center; White hits it with e3, c4 and d4.',
          '2...f6', '흑이 f폰으로 e5를 지키고 큰 중앙을 세워요. 백은 e3, c4, d4로 그 중앙을 쳐요.'),
        V('b4 e5 a3 d5 Bb2 Bd6 e3 Nf6', 'Bugayev Attack, 2.a3', 'White protects b4 first; Black takes the center with ...d5.',
          '부가예프 어택, 2.a3', '백이 먼저 b4를 지켜요. 흑은 ...d5로 중앙을 잡아요.'),
        V('b4 d5 Bb2 Nf6 e3 e6 b5 c5', '1...d5', 'A quiet line: Black develops normally and White uses b5 to gain space.',
          '1...d5', '조용한 갈래예요. 흑은 평범하게 전개하고 백은 b5로 공간을 얻어요.')],
  traps=[TR('b4 e5 Bb2 Bxb4 Bxe5 Nc6 Bxg7', '3...Nc6? 4.Bxg7',
            'After 2...Bxb4 3.Bxe5 the g7 pawn hangs. 3...Nf6 blocks the diagonal; the natural 3...Nc6? loses g7, and the h8 rook is next. White scores about 80% after 3...Nc6.',
            '3...Nc6? 4.Bxg7', '2...Bxb4 3.Bxe5 뒤 g7 폰이 걸려 있어요. 3...Nf6가 대각선을 막는데, 자연스러운 3...Nc6?는 g7을 잃고 h8 룩까지 위험해져요. 3...Nc6 뒤 백 점수는 80% 정도예요.')])

# ---------------------------------------------------------------- irregular
O('van-geet-opening', 'w', 'irregular', 'Nc3', ['Van Geet Opening'],
  en=dict(name='Van Geet Opening (1.Nc3)', title='Van Geet Opening (1.Nc3): 1...d5, 1...e5 and Stats by Rating',
          desc='The Van Geet Opening (1.Nc3): 1...d5 2.e4 with 2...d4 or 2...dxe4, the Dunst-Perrenet Gambit, 1...e5 into the Vienna, and reply rates by rating.',
          lead='1.Nc3 develops a knight and invites 1...d5 2.e4 or 1...e5 2.e4, which lead to a Vienna Game, a Scandinavian-like game or something new. It is flexible but blocks the c-pawn, so most games turn into 1.e4 openings.',
          white=['Against 1...d5, 2.e4 is the main move; after 2...d4 drop back with 3.Nce2 and follow with Ng3, Nf3 and Bc4.',
                 'Against 1...e5, 2.e4 is a Vienna Game and 2.Nf3 keeps the game independent.',
                 'Against 1...Nf6 or 1...c5, 2.e4 leads to an Alekhine, a Vienna or a Closed Sicilian.'],
          black=['1...d5 with 2...d4 gains space and pushes the knight away.',
                 '1...e5 and 1...c5 lead to well-known 1.e4 positions you may already play.',
                 '1...Nf6 with ...d5 is a solid way to avoid White’s preparation.'],
          club='After 1...d5 2.e4 d4, nine in ten players at 2000+ drop back with 3.Nce2 and White scores about 56%. Below 1200 most knights jump forward to d5 or b5 instead, and White scores only about 44%. White scores about 51% after 1.Nc3 overall.'),
  ko=dict(name='반 헤트 오프닝(1.Nc3)', title='반 헤트 오프닝(1.Nc3): 1...d5·1...e5, 레이팅별 응수',
          desc='반 헤트 오프닝(1.Nc3) 정리: 1...d5 2.e4와 2...d4·2...dxe4, 둔스트-페레넷 갬빗, 비엔나로 가는 1...e5, 레이팅별로 많이 두는 응수.',
          lead='1.Nc3는 나이트를 전개하고 1...d5 2.e4나 1...e5 2.e4를 불러요. 비엔나 게임, 스칸디나비안 같은 판, 또는 새로운 판이 돼요. 유연하지만 c폰을 막아서 대부분 1.e4 오프닝으로 바뀌어요.',
          white=['1...d5에는 2.e4가 주요 수예요. 2...d4 뒤엔 3.Nce2로 물러나 Ng3, Nf3, Bc4로 이어 가요.',
                 '1...e5에는 2.e4가 비엔나 게임이고, 2.Nf3는 따로 선 판을 지켜요.',
                 '1...Nf6나 1...c5에는 2.e4로 알레힌, 비엔나, 클로즈드 시실리안이 돼요.'],
          black=['1...d5와 2...d4는 공간을 얻고 나이트를 쫓아내요.',
                 '1...e5와 1...c5는 이미 둘지도 모르는 잘 알려진 1.e4 판으로 가요.',
                 '1...Nf6와 ...d5는 백의 준비를 피하는 단단한 방법이에요.'],
          club='1...d5 2.e4 d4 뒤 2000 이상에서는 열에 아홉이 3.Nce2로 물러나고 백 점수는 56% 정도예요. 1200 미만에서는 나이트가 d5나 b5로 뛰어드는 일이 더 많고, 백 점수는 44% 정도뿐이에요. 1.Nc3 뒤 전체 백 점수는 51% 정도예요.'),
  vars=[V('Nc3 d5 e4 d4 Nce2 e5 Ng3', '1...d5 2.e4 d4', 'Black gains space; White drops back to e2 and plays Ng3, Nf3 and Bc4. White scores about 59% after 4.Ng3 here.',
          '1...d5 2.e4 d4', '흑이 공간을 얻어요. 백은 e2로 물러나 Ng3, Nf3, Bc4를 둬요. 여기서 4.Ng3 뒤 백 점수는 59% 정도예요.'),
        V('Nc3 d5 e4 dxe4 Nxe4', '2...dxe4 3.Nxe4', 'Black takes on e4 and White takes back, a Scandinavian-like game; Black develops with ...Nf6 or ...Bf5.',
          '2...dxe4 3.Nxe4', '흑이 e4에서 받고 백이 되잡아요. 스칸디나비안 같은 판이고, 흑은 ...Nf6나 ...Bf5로 전개해요.'),
        V('Nc3 d5 e4 dxe4 d3', 'Dunst-Perrenet Gambit, 3.d3', 'White gives the d-pawn for quick development, like a Blackmar-Diemer. About nine in ten take with 3...exd3.',
          '둔스트-페레넷 갬빗, 3.d3', '블랙마-디머처럼 백이 d폰을 주고 빨리 전개해요. 열에 아홉 정도가 3...exd3로 받아요.'),
        V('Nc3 e5 Nf3 Nc6 d4', '1...e5 2.Nf3 Nc6 3.d4', 'White avoids the Vienna and opens the center with d4; most players take with 3...exd4.',
          '1...e5 2.Nf3 Nc6 3.d4', '백이 비엔나를 피하고 d4로 중앙을 열어요. 대부분 3...exd4로 받아요.'),
        V('Nc3 e5 e4', '1...e5 2.e4', 'This is the Vienna Game, which has its own guide.',
          '1...e5 2.e4', '비엔나 게임이 돼요. 따로 해설이 있어요.')],
  traps=[])

O('vant-kruijs-opening', 'w', 'irregular', 'e3', ["Van't Kruijs Opening"],
  en=dict(name='Van’t Kruijs Opening (1.e3)', title='Van’t Kruijs Opening (1.e3): Setups and Stats by Rating',
          desc='The Van’t Kruijs Opening (1.e3): what to play after 1...e5 and 1...d5, transpositions to 1.d4 setups, the early Qh5 and reply rates by rating.',
          lead='1.e3 opens the f1 bishop and the queen’s diagonal but takes no central square. It often transposes: with d4 later it becomes a quiet 1.d4 system, with b3 a Nimzo-Larsen, with c4 an English. It is especially common below 1200, where nearly three in ten of the 1.e3 games here are played.',
          white=['Follow with d4 for a Colle- or London-like setup, or b3 and Bb2 for a Nimzo-Larsen.',
                 'Against 1...e5, 2.d4 hits the center at once and is the most common move at every level.',
                 'An early Qh5 or Qf3 with Bc4 sets traps but is easy to meet with ...Nc6, ...g6 or ...Qe7.'],
          black=['Take the center: 1...e5 and 1...d5 are the most common and the most natural.',
                 'After 1...e5 2.d4, 2...exd4 3.exd4 d5 gives a symmetrical, easy game.',
                 'Watch f7 against early Qh5 and Bc4 ideas.'],
          club='Below 1200, about half the players answer 1.e3 with 1...e5, and 2.Qh5 is then White’s second most common move. At 2000+ replies spread out, and after 1...e5 2.d4 leads at 38%. White scores about 50% after 1.e3 at every level.'),
  ko=dict(name='반트 크라위스 오프닝(1.e3)', title='반트 크라위스 오프닝(1.e3): 배치와 레이팅별 응수',
          desc='반트 크라위스 오프닝(1.e3) 정리: 1...e5와 1...d5 뒤 둘 수, 1.d4 배치로 넘어가기, 이른 Qh5, 레이팅별로 많이 두는 응수.',
          lead='1.e3는 f1 비숍과 퀸의 대각선을 열지만 중앙 칸은 잡지 않아요. 다른 오프닝으로 자주 넘어가요. 나중에 d4를 두면 조용한 1.d4 체계, b3면 님조-라르센, c4면 잉글리시예요. 특히 1200 미만에서 흔해서, 여기 1.e3 판의 열에 셋 가까이가 그 레이팅대에서 나와요.',
          white=['d4로 콜레나 런던 같은 배치를 만들거나, b3와 Bb2로 님조-라르센을 만들어요.',
                 '1...e5에는 2.d4로 바로 중앙을 쳐요. 모든 레이팅대에서 가장 많은 수예요.',
                 'Bc4와 함께 두는 이른 Qh5나 Qf3는 함정을 놓지만 ...Nc6, ...g6, ...Qe7로 쉽게 막혀요.'],
          black=['중앙을 잡아요. 1...e5와 1...d5가 가장 많고 가장 자연스러워요.',
                 '1...e5 2.d4 뒤 2...exd4 3.exd4 d5는 대칭이고 편한 판을 줘요.',
                 '이른 Qh5와 Bc4에는 f7을 조심해요.'],
          club='1200 미만에서는 절반 정도가 1.e3에 1...e5로 받고, 그 뒤 2.Qh5가 백의 두 번째로 많은 수예요. 2000 이상에서는 응수가 고르게 나뉘고, 1...e5 뒤엔 2.d4가 38%로 앞서요. 1.e3 뒤 백 점수는 모든 레이팅대에서 50% 정도예요.'),
  vars=[V('e3 e5 d4 exd4 exd4 d5', '1...e5 2.d4', 'After 2...exd4 3.exd4 d5 the pawns are symmetrical and the game is quiet.',
          '1...e5 2.d4', '2...exd4 3.exd4 d5 뒤 폰 구조가 대칭이고 판이 조용해요.'),
        V('e3 e5 b3 d5 Bb2 Nc6', '1...e5 2.b3', 'A Nimzo-Larsen setup with e3 already played; the b2 bishop hits e5.',
          '1...e5 2.b3', 'e3를 먼저 둔 님조-라르센 배치예요. b2 비숍이 e5를 쳐요.'),
        V('e3 d5 d4 Nf6 Nf3 e6 Bd3', '1...d5 2.d4', 'This becomes a Colle System, which has its own guide.',
          '1...d5 2.d4', '콜레 시스템이 돼요. 따로 해설이 있어요.'),
        V('e3 e5 Qh5 Nc6 Bc4 g6', '1...e5 2.Qh5', 'A quick shot at f7 and e5; ...Nc6 and ...g6 shut it down, and the queen has to move again.',
          '1...e5 2.Qh5', 'f7과 e5를 노리는 빠른 공격이에요. ...Nc6와 ...g6로 막으면 퀸이 또 움직여야 해요.')],
  traps=[])

O('mieses-opening', 'w', 'irregular', 'd3', ['Mieses Opening', 'Valencia Opening'],
  en=dict(name='Mieses Opening (1.d3)', title='Mieses Opening (1.d3): Setups, Transpositions and Stats',
          desc='The Mieses Opening (1.d3): reversed Pirc and King’s Indian setups, the King’s Indian Attack, what happens after 1...e5 and 1...d5, and reply rates by rating.',
          lead='1.d3 opens the c1 bishop and supports a later e4, but gives Black the center for free. With g3, Bg2 and Nf3 it becomes a King’s Indian Attack or a Pirc with colors reversed; with e4 it can turn into a quiet 1.e4 game.',
          white=['g3, Bg2, Nf3, O-O and e4 is the most useful plan: a King’s Indian Attack.',
                 'After 1...e5, 2.e4 gives a King’s Pawn Game with d3; 2.Nf3 or 2.g3 keeps the reversed Pirc.',
                 'Do not expect an advantage; aim for a setup you know.'],
          black=['Take the full center with ...d5 and ...e5, or ...d5 with ...Nf6 and ...c5.',
                 'Develop normally: White’s first move gives you time, not problems.',
                 'Against a King’s Indian Attack setup, ...c5, ...Nc6 and ...b5 is active play.'],
          club='White scores only about 49% after 1.d3, and about 47% below 1200, the lowest of the eleven most common first moves here. At 2000+ it is about even. Below 1200 1...e5 is the top reply, at 2000+ 1...d5.'),
  ko=dict(name='미제스 오프닝(1.d3)', title='미제스 오프닝(1.d3): 배치·다른 오프닝으로 넘어가기·응수',
          desc='미제스 오프닝(1.d3) 정리: 색을 바꾼 피르츠와 킹스 인디언 배치, 킹스 인디언 어택, 1...e5와 1...d5 뒤 흐름, 레이팅별로 많이 두는 응수.',
          lead='1.d3는 c1 비숍을 열고 나중의 e4를 받치지만, 흑에게 중앙을 공짜로 줘요. g3, Bg2, Nf3를 두면 킹스 인디언 어택이나 색을 바꾼 피르츠가 되고, e4를 두면 조용한 1.e4 판으로 바뀔 수 있어요.',
          white=['g3, Bg2, Nf3, O-O, e4가 가장 쓸모 있는 계획이에요. 킹스 인디언 어택이에요.',
                 '1...e5 뒤 2.e4는 d3를 둔 킹스 폰 게임이 되고, 2.Nf3나 2.g3는 색을 바꾼 피르츠를 지켜요.',
                 '이점을 기대하지 말고 아는 배치로 가요.'],
          black=['...d5와 ...e5로 중앙을 다 잡거나, ...d5에 ...Nf6와 ...c5를 둬요.',
                 '평범하게 전개해요. 백의 첫 수는 문제가 아니라 시간을 줘요.',
                 '킹스 인디언 어택 배치에는 ...c5, ...Nc6, ...b5가 활발한 판이에요.'],
          club='1.d3 뒤 백 점수는 49% 정도, 1200 미만에서는 47% 정도로, 여기서 가장 많이 두는 첫 수 열한 개 가운데 가장 낮아요. 2000 이상에서는 거의 균형이에요. 1200 미만에서는 1...e5가, 2000 이상에서는 1...d5가 가장 많은 응수예요.'),
  vars=[V('d3 d5 Nf3 Nf6 g3 c5 Bg2 Nc6 O-O e5', 'King’s Indian Attack setup', 'White builds g3, Bg2 and O-O, then e4; Black grabs the center with ...c5, ...Nc6 and ...e5.',
          '킹스 인디언 어택 배치', '백이 g3, Bg2, O-O 뒤 e4를 둬요. 흑은 ...c5, ...Nc6, ...e5로 중앙을 잡아요.'),
        V('d3 e5 Nf3 Nc6 g3 d5 Bg2', 'Reversed Pirc, 1...e5', 'White plays a Pirc Defense with colors reversed and an extra move.',
          '색을 바꾼 피르츠, 1...e5', '백이 색을 바꾸고 한 수 더 둔 피르츠 디펜스를 둬요.'),
        V('d3 d5 e4 dxe4', '1...d5 2.e4', 'White offers to trade center pawns; about two in three take with 2...dxe4, and after 3.dxe4 Black can trade queens at once.',
          '1...d5 2.e4', '백이 중앙 폰 교환을 권해요. 셋에 둘 정도가 2...dxe4로 받고, 3.dxe4 뒤 흑은 바로 퀸을 바꿀 수 있어요.'),
        V('d3 e5 e4', '1...e5 2.e4', 'This becomes a King’s Pawn Game with d3, covered in the 1.e4 e5 guide.',
          '1...e5 2.e4', 'd3를 둔 킹스 폰 게임이 돼요. 1.e4 e5 해설에서 다뤄요.')],
  traps=[])

O('grob-opening', 'w', 'irregular', 'g4', ['Grob Opening'],
  en=dict(name='Grob Opening (1.g4)', title='Grob Opening (1.g4): Grob Gambit, Traps and Stats by Rating',
          desc='The Grob Opening (1.g4): the Grob Gambit 1...d5 2.Bg2 Bxg4 3.c4, answers to 1...e5, the fastest mate after 2.f4??, and reply rates by rating.',
          lead='1.g4 attacks nothing and loosens White’s kingside, but it opens the g2 diagonal toward d5 and b7 at once. It is a favorite of blitz players who want unusual positions from move one.',
          white=['Against 1...d5, 2.Bg2 attacks d5; after 2...Bxg4 3.c4 the pressure on the long diagonal is worth the pawn.',
                 'Against 1...e5, Bg2, d3 and h3 keep the g-pawn safe; never play f3 or f4 while ...Qh4 is possible.',
                 'Qb3 often joins the attack on b7.'],
          black=['Take the center with 1...d5 or 1...e5 and develop quickly.',
                 'After 1...d5 2.Bg2, 2...c6 is the safe answer: it holds d5 and blunts the g2 bishop.',
                 'Look for ...Qh4 and ...h5: the g4 pawn and f2 are White’s weak points.'],
          club='Below 1200 White scores only about 46% with 1.g4; at 2000+ about 51%. After the Grob Gambit 1...d5 2.Bg2 Bxg4 3.c4, White scores about 59%, so taking the pawn is risky. At 2000+ about three in ten answer 2.Bg2 with the safe 2...c6.'),
  ko=dict(name='그롭 오프닝(1.g4)', title='그롭 오프닝(1.g4): 그롭 갬빗·함정·레이팅별 응수',
          desc='그롭 오프닝(1.g4) 정리: 그롭 갬빗 1...d5 2.Bg2 Bxg4 3.c4, 1...e5 상대로 둘 수, 2.f4?? 뒤 가장 빠른 메이트, 레이팅별로 많이 두는 응수.',
          lead='1.g4는 아무것도 공격하지 않고 백 킹 쪽을 헐겁게 하지만, g2 대각선을 바로 열어 d5와 b7을 겨눠요. 첫 수부터 낯선 판을 원하는 블리츠 선수들이 좋아해요.',
          white=['1...d5에는 2.Bg2로 d5를 쳐요. 2...Bxg4 3.c4 뒤 긴 대각선 압박이 폰 하나 값을 해요.',
                 '1...e5에는 Bg2, d3, h3로 g폰을 지켜요. ...Qh4가 가능할 때 f3나 f4는 절대 두지 말아요.',
                 'Qb3가 b7 공격에 자주 가세해요.'],
          black=['1...d5나 1...e5로 중앙을 잡고 빨리 전개해요.',
                 '1...d5 2.Bg2 뒤 2...c6가 안전한 응수예요. d5를 지키고 g2 비숍을 무디게 해요.',
                 '...Qh4와 ...h5를 노려요. g4 폰과 f2가 백의 약점이에요.'],
          club='1200 미만에서는 1.g4 뒤 백 점수가 46% 정도뿐이고, 2000 이상에서는 51% 정도예요. 그롭 갬빗 1...d5 2.Bg2 Bxg4 3.c4 뒤 백 점수는 59% 정도라서 폰을 받는 건 위험해요. 2000 이상에서는 열에 셋 정도가 2.Bg2에 안전한 2...c6로 받아요.'),
  vars=[V('g4 d5 Bg2 Bxg4 c4 c6', 'Grob Gambit, 2...Bxg4 3.c4', 'White gives the g-pawn and hits d5 and b7; Black holds with ...c6 and has to watch Qb3.',
          '그롭 갬빗, 2...Bxg4 3.c4', '백이 g폰을 주고 d5와 b7을 쳐요. 흑은 ...c6로 버티고 Qb3를 조심해야 해요.'),
        V('g4 d5 Bg2 c6', '2...c6', 'Black keeps the pawn on d5 and closes the diagonal; White plays h3 or g5.',
          '2...c6', '흑이 d5 폰을 지키고 대각선을 닫아요. 백은 h3나 g5를 둬요.'),
        V('g4 d5 g5', '2.g5', 'White pushes again instead of defending g4; Black takes the center with 2...e5 in about half the games.',
          '2.g5', '백이 g4를 지키는 대신 한 번 더 밀어요. 흑은 절반 정도가 2...e5로 중앙을 잡아요.'),
        V('g4 e5 Bg2 d5', '1...e5 2.Bg2 d5', 'Black builds the full center; White hits it with c4 or d3 and keeps an eye on h4.',
          '1...e5 2.Bg2 d5', '흑이 중앙을 다 세워요. 백은 c4나 d3로 그 중앙을 치고 h4를 계속 살펴요.')],
  traps=[TR('g4 e5 f4 Qh4#', '1...e5 2.f4?? Qh4#',
            'The fastest possible mate against White: after 1.g4 e5 2.f4?? the e1–h4 diagonal is wide open and 2...Qh4 is mate. With the g-pawn gone, the f-pawn must stay home.',
            '1...e5 2.f4?? Qh4#', '백이 당할 수 있는 가장 빠른 메이트예요. 1.g4 e5 2.f4??면 e1–h4 대각선이 활짝 열려서 2...Qh4가 메이트예요. g폰이 나간 뒤엔 f폰을 그대로 둬야 해요.', end='mate')])

O('rare-first-moves', 'w', 'irregular', 'c3',
  ['Saragossa Opening', 'Barnes Opening', "Anderssen's Opening", 'Clemenz Opening', 'Ware Opening', 'Kádas Opening', 'Sodium Attack', 'Amar Opening', 'Global Opening', 'Creepy Crawly Formation'],
  en=dict(name='Rare First Moves', title='Rare First Moves: 1.c3, 1.a3, 1.f3, 1.h3, 1.h4 and More',
          desc='Rare first moves for White: the Saragossa 1.c3, Anderssen 1.a3, Barnes 1.f3, Clemenz 1.h3, Ware 1.a4, Kádas 1.h4, 1.Na3 and 1.Nh3, with reply rates by rating.',
          lead='Every first move has a name. These are rare because they do little for the center or development, but none of them loses by force. Against all of them the simple recipe works: take the center with ...e5 or ...d5, develop and castle.',
          white=['1.c3 and 1.a3 are the most useful: they can turn into a reversed Caro-Kann, a 1.d4 system or an English with a3.',
                 '1.f3 (the Barnes) loosens the e1–h4 diagonal; after 1...e5 avoid g4 and Kf2 adventures.',
                 'After wing moves like 1.a4, 1.h4 and 1.h3, continue with a normal setup such as d4, Nf3 and e3.'],
          black=['1...e5 or 1...d5 and quick development is enough against every move here.',
                 'Do not copy White’s odd move; use the extra time in the center.',
                 'Against 1.f3, ...e5 and ...d5 build a big center, and ...Qh4+ ideas appear if White loosens g3.'],
          club='Below 1200 every move on this page scores under 50% for White, from about 37% with 1.Na3 to about 49% with 1.c3. At 2000+ most of them score over 50%, and 1.h3 scores about 59%: strong players who choose these moves know what they are doing. 1.c3 is the most played of them, with about 38,000 games here.'),
  ko=dict(name='드문 첫 수', title='드문 첫 수: 1.c3·1.a3·1.f3·1.h3·1.h4와 그 밖의 수',
          desc='백의 드문 첫 수 정리: 사라고사 1.c3, 안데르센 1.a3, 반스 1.f3, 클레멘츠 1.h3, 웨어 1.a4, 카다시 1.h4, 1.Na3, 1.Nh3, 레이팅별로 많이 두는 응수.',
          lead='첫 수마다 이름이 있어요. 이 수들은 중앙이나 전개에 별 도움이 안 돼서 드물지만, 바로 지는 수는 없어요. 모두에게 간단한 방법이 통해요. ...e5나 ...d5로 중앙을 잡고, 전개하고, 캐슬링해요.',
          white=['1.c3와 1.a3가 가장 쓸모 있어요. 색을 바꾼 카로칸, 1.d4 체계, a3를 둔 잉글리시로 갈 수 있어요.',
                 '1.f3(반스)는 e1–h4 대각선을 헐겁게 해요. 1...e5 뒤 g4나 Kf2 같은 모험은 피해요.',
                 '1.a4, 1.h4, 1.h3 같은 날개 수 뒤엔 d4, Nf3, e3 같은 평범한 배치로 이어 가요.'],
          black=['여기 나온 모든 수에 1...e5나 1...d5와 빠른 전개면 충분해요.',
                 '백의 이상한 수를 따라 하지 말고, 얻은 시간을 중앙에 써요.',
                 '1.f3에는 ...e5와 ...d5로 큰 중앙을 세워요. 백이 g3를 헐겁게 하면 ...Qh4+ 수법이 생겨요.'],
          club='1200 미만에서는 이 페이지의 모든 수가 백 점수 50% 아래예요. 1.Na3의 37% 정도부터 1.c3의 49% 정도까지예요. 2000 이상에서는 대부분 50%를 넘고, 1.h3는 59% 정도예요. 이런 수를 고르는 고수는 알고 두는 거예요. 가장 많이 두는 건 1.c3로, 여기서 3만 8천 판 정도예요.'),
  vars=[V('c3 e5 d4 exd4 cxd4 d5', 'Saragossa, 1.c3', 'White prepares d4 with pawn support; after 1...e5 2.d4 exd4 3.cxd4 d5 the center is symmetrical.',
          '사라고사, 1.c3', '백이 폰으로 받친 d4를 준비해요. 1...e5 2.d4 exd4 3.cxd4 d5 뒤 중앙이 대칭이에요.'),
        V('a3 e5 c4', 'Anderssen, 1.a3', 'A waiting move. With c4 it becomes an English with a3 already played.',
          '안데르센, 1.a3', '기다리는 수예요. c4를 두면 a3를 먼저 둔 잉글리시가 돼요.'),
        V('f3 e5 Kf2', 'Barnes, 1.f3 e5 2.Kf2', 'A joke line seen in online blitz. White scores about 44% after it, and about 37% below 1200.',
          '반스, 1.f3 e5 2.Kf2', '온라인 블리츠에서 보이는 장난 같은 수순이에요. 이 수 뒤 백 점수는 44% 정도, 1200 미만에서는 37% 정도예요.'),
        V('h3', 'Clemenz, 1.h3', 'Below 1200 White scores about 43% with it; at 2000+ about 59%, with many draws.',
          '클레멘츠, 1.h3', '1200 미만에서는 백 점수가 43% 정도인데, 2000 이상에서는 59% 정도이고 무승부도 많아요.'),
        V('a4', 'Ware, 1.a4', 'The rook can come out via a3, but the move does nothing for the center. White scores about 44% overall.',
          '웨어, 1.a4', '룩이 a3로 나올 수 있지만 중앙에는 도움이 안 돼요. 전체 백 점수는 44% 정도예요.'),
        V('h4', 'Kádas, 1.h4', 'After 1.c3 the most played move on this page, with about 19,000 games; White scores about 44%.',
          '카다시, 1.h4', '이 페이지에서 1.c3 다음으로 많이 둔 수로 1만 9천 판 정도예요. 백 점수는 44% 정도예요.'),
        V('Na3', 'Sodium Attack, 1.Na3', 'The knight heads for c4 or b5. It is the rarest move on this page, with under 2,000 games.',
          '소듐 어택, 1.Na3', '나이트가 c4나 b5로 가려 해요. 이 페이지에서 가장 드문 수로 2천 판이 안 돼요.'),
        V('Nh3', 'Amar, 1.Nh3', 'The knight heads for f4. White scores about 42% overall, the lowest result on this page.',
          '아마르, 1.Nh3', '나이트가 f4로 가려 해요. 전체 백 점수는 42% 정도로 이 페이지에서 가장 낮아요.')],
  traps=[], hub=True)
